/* Interface d'Atelier Zéphyr. État gardé dans le navigateur, avec un code de sauvegarde. */
const KEY="zephyr-etat-v2";
const newTeam=n=>({n,d:[null,null,null],s:[{},{},{}],cv:{},j:[["","",""],["","",""],["","",""]],g:{}});
function exemple(){const a=newTeam("Équipe Alizé"),b=newTeam("Équipe Mistral"),c=newTeam("Équipe Sirocco");
  a.d[0]={p:1,c:1,r:1};b.d[0]={p:1,c:0,r:0};c.d[0]={p:0,c:2,r:2};
  return {exemple:true,ev:false,clos:[true,false,false],corr:false,sel:0,eq:0,teams:[a,b,c],ds:{ans:{},ok:{},tries:0,ouv:["","",""],reveal:false}};}
let S=exemple();
try{const raw=localStorage.getItem(KEY);if(raw){const o=JSON.parse(raw);if(valide(o))S=o;}}catch(e){}
S.lec=S.lec||{};S.ds.rev=S.ds.rev||{};S.ds.revOuv=S.ds.revOuv||{};
function valide(o){return o&&Array.isArray(o.teams)&&Array.isArray(o.clos)&&o.ds&&o.teams.every(t=>t&&Array.isArray(t.d)&&Array.isArray(t.s));}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){}}
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const num=n=>n.toLocaleString("fr-FR");
const eur=n=>(n<0?"−":"")+Math.abs(n).toLocaleString("fr-FR")+" €";
const sig=n=>(n>0?"+":n<0?"−":"")+Math.abs(n).toLocaleString("fr-FR");
const neg=n=>n<0?' class="neg"':"";
const PR=()=>params(S.ev);
const calc=t=>simul(t.d,PR());
const annee=()=>{const i=S.clos.indexOf(false);return i<0?3:i;};
const dClos=()=>S.clos.lastIndexOf(true);
const parse=s=>{const t=String(s||"").replace(/[\s  €]/g,"").replace("−","-").replace(",",".");return t===""||isNaN(t)?null:Number(t);};
const col=i=>`var(--c${i%8+1})`;
const coef=k=>(k/100).toFixed(2).replace(".",",");
const team=()=>{if(S.eq>=S.teams.length)S.eq=0;return S.teams[S.eq];};
const selEq=()=>`<label>Équipe<select id="eq">${S.teams.map((o,i)=>`<option value="${i}" ${i===S.eq?"selected":""}>${esc(o.n)}</option>`).join("")}</select></label>`;
const vide=()=>`<div class="panel"><p>Aucune équipe. Créez-les dans le mode Enseignant, page Conduite.</p></div>`;

const MODES=[["apprendre","Apprendre",[["accueil","Présentation"],["manuel","Manuel"],["texte","Texte parlé"],["lecons","Leçons et exercices"],["excel","Formules Excel"],["fichiers","Fichiers à télécharger"]]],
 ["decouvrir","Découvrir l'entreprise",[["cas","Le cas"],["canevas","Business model"],["environnement","Environnement"],["ressources","Ressources et compétences"],["marche","Marché et SWOT"],["notions","Notions"]]],
 ["simuler","Simuler trois années",[["classe","Écran de classe"],["decisions","Décisions"],["bord","Tableau de bord"],["detail","Tableau détaillé"],["regles","Règles"]]],
 ["controle","Contrôle de gestion",[["sujet","1. Sujet et annexes"],["ecarts","2. Calcul des écarts"],["passage","3. Tableau de passage"],["diagnostic","4. Diagnostic"],["bilan","5. Bilan du projet"]]],
 ["enseignant","Enseignant",[["conduite","Conduite"],["notation","Notation"],["reperes","Repères"],["sauvegarde","Sauvegarde"]]]];

/* ---------- graphiques ---------- */
function bars(labels,vals,o){o=o||{};const W=520,H=220,L=70,B=30,T=14,all=vals.concat([0]);let lo=Math.min(...all),hi=Math.max(...all);if(hi===lo)hi=lo+1;
  const pad=(hi-lo)*.08;hi+=hi>0?pad:0;lo-=lo<0?pad:0;const y=v=>T+(hi-v)*(H-T-B)/(hi-lo),bw=(W-L-20)/vals.length;let g=`<line x1="${L}" x2="${W-10}" y1="${y(0)}" y2="${y(0)}" stroke="var(--muted)"/>`;
  vals.forEach((v,i)=>{const x=L+i*bw+bw*.2,h=Math.abs(y(v)-y(0));g+=`<rect x="${x}" y="${Math.min(y(v),y(0))}" width="${bw*.6}" height="${Math.max(h,1)}" rx="3" fill="${v<0?"var(--bad)":(o.color||"var(--accent)")}"/><text x="${x+bw*.3}" y="${v<0?y(v)+14:y(v)-5}" text-anchor="middle" style="fill:var(--fg);font-weight:600">${o.fmt?o.fmt(v):num(v)}</text><text x="${x+bw*.3}" y="${H-8}" text-anchor="middle">${labels[i]}</text>`;});
  return `<div class="scroll"><svg viewBox="0 0 ${W} ${H}" width="100%" style="min-width:320px;max-width:560px" role="img" aria-label="${esc(o.label||"")}">${g}</svg></div>`;}
function courbe(){const n=dClos()+1;if(n<1)return "";const series=S.teams.map(t=>[PR().t0,...calc(t).slice(0,n).map(r=>r.fin)]);
  const all=series.flat().concat([0]);let lo=Math.min(...all),hi=Math.max(...all);const step=hi-lo>1500000?500000:250000;lo=Math.floor(lo/step)*step;hi=Math.ceil(hi/step)*step;if(hi===lo)hi=lo+step;
  const W=760,H=320,L=78,R=160,T=16,B=34,x=i=>L+i*(W-L-R)/3,y=v=>T+(hi-v)*(H-T-B)/(hi-lo);let g="";
  for(let v=lo;v<=hi;v+=step)g+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="${v===0?"var(--bad)":"var(--line)"}" stroke-width="${v===0?2:1}"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end">${num(v/1000)} k€</text>`;
  ["Départ","Fin an 1","Fin an 2","Fin an 3"].forEach((l,i)=>g+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${l}</text>`);
  const ends=series.map((s,i)=>({i,y:y(s[s.length-1])})).sort((a,b)=>a.y-b.y);for(let k=1;k<ends.length;k++)if(ends[k].y-ends[k-1].y<15)ends[k].y=ends[k-1].y+15;
  series.forEach((s,i)=>{g+=`<polyline fill="none" stroke="${col(i)}" stroke-width="3" stroke-linejoin="round" points="${s.map((v,j)=>x(j)+","+y(v)).join(" ")}"/>`;s.forEach((v,j)=>g+=`<circle cx="${x(j)}" cy="${y(v)}" r="4" fill="${col(i)}"/>`);
    g+=`<text x="${x(s.length-1)+10}" y="${ends.find(o=>o.i===i).y+4}" style="fill:${col(i)};font-weight:600">${esc(S.teams[i].n).slice(0,22)}</text>`;});
  return `<div class="scroll"><svg viewBox="0 0 ${W} ${H}" width="100%" style="min-width:560px" role="img" aria-label="Trésorerie des équipes en fin d'année">${g}</svg></div><p class="note">Trésorerie en fin d'année, en milliers d'euros. Sous la ligne rouge, l'équipe est en alerte banque.</p>`;}
function cascade(o){const st=[["Résultat budgété",o.resB,1],["Prix de vente",o.ePrix],["Volume global",o.eVol],["Composition",o.eComp],["Fibre",-o.eFib],["Kits",-o.eKit],["Main-d'œuvre",-o.eMod],["Charges indirectes",-o.eCI],["Structure",-o.eStr],["Résultat réel",o.resR,1]];
  const W=820,H=340,L=74,T=20,B=64;let cum=0,pts=[];st.forEach(s=>{if(s[2]){pts.push([0,s[1]]);cum=s[1];}else{pts.push([cum,cum+s[1]]);cum+=s[1];}});
  let lo=Math.min(0,...pts.flat()),hi=Math.max(0,...pts.flat());const pad=(hi-lo)*.1;lo-=pad;hi+=pad;const y=v=>T+(hi-v)*(H-T-B)/(hi-lo),bw=(W-L-10)/st.length;
  let g=`<line x1="${L}" x2="${W-10}" y1="${y(0)}" y2="${y(0)}" stroke="var(--muted)"/>`;[-100000,0,100000,200000].forEach(v=>g+=`<text x="${L-8}" y="${y(v)+4}" text-anchor="end">${num(v/1000)} k€</text>`);
  st.forEach((s,i)=>{const [a,b]=pts[i],x=L+i*bw+bw*.15,f=s[2]?"var(--accent)":s[1]<0?"var(--bad)":s[1]>0?"var(--good)":"var(--muted)";
    g+=`<rect x="${x}" y="${Math.min(y(a),y(b))}" width="${bw*.7}" height="${Math.max(Math.abs(y(a)-y(b)),2)}" rx="3" fill="${f}"/><text x="${x+bw*.35}" y="${Math.min(y(a),y(b))-6}" text-anchor="middle" style="fill:var(--fg);font-weight:600">${s[2]?num(s[1]/1000):sig(s[1]/1000)}</text>`;
    const w=s[0].split(" ");g+=`<text x="${x+bw*.35}" y="${H-B+18}" text-anchor="middle">${w[0]}</text>`+(w.length>1?`<text x="${x+bw*.35}" y="${H-B+33}" text-anchor="middle">${w.slice(1).join(" ")}</text>`:"");
    if(i<st.length-1)g+=`<line x1="${x+bw*.7}" x2="${x+bw}" y1="${y(b)}" y2="${y(b)}" stroke="var(--line)"/>`;});
  return `<div class="scroll"><svg viewBox="0 0 ${W} ${H}" width="100%" style="min-width:680px" role="img" aria-label="Passage du résultat budgété au résultat réel">${g}</svg></div><p class="note">Effet de chaque écart sur le résultat, en milliers d'euros. Rouge : l'écart réduit le résultat. Vert : il l'augmente.</p>`;}


/* ---------- choix du parcours ---------- */
let PARC="";try{PARC=localStorage.getItem("zephyr-parcours")||"";}catch(e){}
function setParc(v){PARC=v;try{if(v)localStorage.setItem("zephyr-parcours",v);else localStorage.removeItem("zephyr-parcours");}catch(e){}}
const TEACH=["conduite","notation","reperes","sauvegarde"];
const lecVisible=x=>PARC==="dscg"?/DSCG/.test(x.niv):/DU/.test(x.niv);
function choixParcours(){return `<div class="panel big"><h2>Choisissez votre parcours</h2><p class="lead">Ce choix détermine les leçons, les exercices et les calculs qui vous sont proposés.</p><div class="grid2"><button class="pri" data-parc="du">Parcours DU PaRéO<small>Chiffres ronds, leçons 1 à 6</small></button><button class="pri" data-parc="dscg">Parcours DSCG / Master<small>Deux décimales, leçons 6 à 8 et projet d'écarts</small></button></div></div>`;}
const changeBar=()=>"";
const barreParc=()=>`<a href="#accueil">Accueil</a><span class="tag">Parcours :</span><div class="seg"><button data-parc="du" aria-pressed="${PARC==="du"}">DU PaRéO</button><button data-parc="dscg" aria-pressed="${PARC==="dscg"}">DSCG / Master</button></div>${PARC?`<button data-parc="reset">Revenir au choix du parcours</button>`:""}`;

/* ---------- mode Apprendre ---------- */
let lec=0,dlMsg="";
const etape=(n,t,d,l)=>`<li><b>${t}</b> ${d} ${l.map(x=>`<a href="#${x[0]}">${x[1]}</a>`).join(" · ")}</li>`;
function vAccueil(){const fait=LECONS.filter((L,i)=>{const st=S.lec[i];return st&&L.qs.every((q,k)=>st.ok[k]===true);}).length;
  return `<div class="panel"><h2>À quoi sert cette application</h2><p class="lead">Atelier Zéphyr est une entreprise fictive qui conçoit des drones d'inspection. L'application fait apprendre la gestion en trois temps : comprendre les notions, les appliquer sur l'entreprise, puis analyser les résultats.</p>
  <div class="grid"><div class="fact"><b>${LECONS.length} leçons</b><span>théorie, formules, exemple pas à pas, exercices corrigés</span></div><div class="fact"><b>3 années</b><span>de décisions en équipe, avec calcul à la main</span></div><div class="fact"><b>27 écarts</b><span>à calculer dans le projet de contrôle de gestion</span></div><div class="fact"><b>${fait} / ${LECONS.length}</b><span>leçons réussies sur ce poste</span></div></div></div>
  <div class="panel"><h2>Comment elle s'utilise</h2><ul><li><b>En salle :</b> l'enseignant projette l'application. Les équipes travaillent sur papier ou sur le classeur, et annoncent leurs décisions.</li><li><b>En visioconférence :</b> l'enseignant partage son écran. Les étudiants à distance suivent le même affichage et envoient leurs décisions par la discussion.</li><li><b>En autonomie :</b> chacun peut ouvrir les leçons et faire les exercices sur son propre appareil. Les réponses restent sur cet appareil.</li></ul><p class="note">La page dit si un calcul est juste, sans donner la réponse avant deux essais. Elle ne remplace pas la correction de l'enseignant.</p></div>
  <div class="panel"><h2>Parcours DU PaRéO : trois séances</h2><ol>${etape(1,"Séance 1.","Découvrir l'entreprise, apprendre à calculer une marge et un résultat, puis jouer l'année 1.",[["lecons","Leçons 1 à 4"],["cas","Le cas"],["canevas","Business model"],["decisions","Décisions"]])}${etape(2,"Séance 2.","Comprendre la trésorerie, présenter un pitch à l'investisseur, jouer l'année 2.",[["lecons","Leçon 5"],["environnement","Environnement"],["marche","Marché et SWOT"],["bord","Tableau de bord"]])}${etape(3,"Séance 3.","Jouer l'année 3, comparer le prévu et le réalisé, présenter le bilan.",[["lecons","Leçon 6"],["detail","Tableau détaillé"],["classe","Écran de classe"]])}</ol></div>
  <div class="panel"><h2>Parcours DSCG : budget et écarts</h2><ol>${etape(1,"Réviser.","Le principe des écarts, l'écart sur marge et les charges indirectes.",[["lecons","Leçons 6 à 8"]])}${etape(2,"Lire le sujet.","L'exercice 3 d'Atelier Zéphyr, avec deux modèles de drones.",[["sujet","Sujet et annexes"]])}${etape(3,"Calculer.","Les 27 valeurs, dans le classeur puis dans l'application.",[["fichiers","Classeur"],["ecarts","Calcul des écarts"]])}${etape(4,"Expliquer.","Le tableau de passage du résultat budgété au résultat réel.",[["passage","Tableau de passage"]])}${etape(5,"Conclure.","La note à la direction, puis le bilan du projet avec vos points de calcul.",[["diagnostic","Diagnostic"],["bilan","Bilan du projet"]])}</ol></div>`;}
function vLecons(){if(!lecVisible(LECONS[lec]))lec=LECONS.findIndex(lecVisible);const L=LECONS[lec],st=S.lec[lec]||{ans:[],ok:[],n:0};
  return `<div class="panel"><h2>Leçons et exercices</h2><div class="lecnav">${LECONS.map((x,i)=>{if(!lecVisible(x))return "";const s=S.lec[i],ok=s&&x.qs.every((q,k)=>s.ok[k]===true);return `<button data-lec="${i}" aria-pressed="${i===lec}">${i+1}. ${x.t}${ok?" ✓":""}<small>${x.niv}</small></button>`;}).join("")}</div></div>
  <div class="panel lecon"><div class="row" style="justify-content:space-between"><h2>${lec+1}. ${L.t}</h2><span class="chip">${L.niv}</span></div>${L.intro.map(p=>`<p>${p}</p>`).join("")}
  <h3>À retenir</h3><ul>${L.points.map(p=>`<li>${p}</li>`).join("")}</ul>
  ${L.formules.length?`<h3>Formules</h3><div class="scroll"><table class="txt"><tbody>${L.formules.map(f=>`<tr><td><b>${f[0]}</b></td><td>= ${f[1]}</td></tr>`).join("")}</tbody></table></div>`:""}
  <h3>Exemple pas à pas : ${L.ex.t}</h3><ol>${L.ex.steps.map(p=>`<li>${p}</li>`).join("")}</ol></div>
  <div class="panel"><h3>À vous</h3><p class="note">Répondez, puis vérifiez. ${S.note?"Parcours noté : les réponses ne s'affichent pas.":"Après la vérification, la réponse attendue et son explication s'affichent pour chaque question à revoir."}</p>
  ${L.qs.map((q,i)=>{const o=st.ok[i],show=o===true||(!S.note&&st.n>=1&&o===false);return `<div class="quest"><p><b>${i+1}.</b> ${q.q}</p>${q.choix?`<div class="choix">${q.choix.map((c,k)=>`<label class="radio"><input type="radio" id="lq-${lec}-${i}-${k}" name="lq-${lec}-${i}" value="${k}" ${String(st.ans[i])===String(k)?"checked":""}> ${c}</label>`).join("")}</div>`:`<input id="lq-${lec}-${i}" inputmode="numeric" value="${esc(st.ans[i]||"")}" aria-label="Réponse ${i+1}">`}
    <span class="check ${o===true?"ok":o===false?"ko":""}">${o===true?"Juste":o===false?"À revoir":""}</span>${show?`<p class="expl">${o===false?`<b>Réponse attendue : ${q.choix?q.choix[q.a]:num(q.a).replace("-","−")}.</b> `:""}${q.expl}</p>`:""}</div>`;}).join("")}
  <div class="row"><button class="pri" id="lec-verif">Vérifier</button>${lec<LECONS.length-1?`<button data-lec="${lec+1}">Leçon suivante</button>`:""}<span class="note">${st.n?st.n+" essai"+(st.n>1?"s":""):""}</span></div></div>`;}
function vFichiers(){return `<div class="panel"><h2>Fichiers à télécharger</h2><p class="note">Le navigateur demande une confirmation avant d'enregistrer chaque fichier.</p><div class="scroll"><table class="txt"><thead><tr><th>Fichier</th><th>Contenu</th><th></th></tr></thead><tbody>
  <tr><td><b>Classeur étudiant</b><br><span class="note">Excel, .xlsx</span></td><td>Les données de la simulation et du projet DSCG, une grille « Ma simulation » et une grille « Mes écarts » à remplir avec ses propres formules. Aucun corrigé.</td><td><button class="pri" data-dl="etudiant">Télécharger</button></td></tr>
  <tr><td><b>Texte des leçons</b><br><span class="note">Texte, .md</span></td><td>Les ${LECONS.length} leçons : notions, formules, exemples pas à pas et exercices avec leurs réponses.</td><td><button class="pri" data-dl="lecons">Télécharger</button></td></tr></tbody></table></div><p class="note">${esc(dlMsg)}</p><p class="note">Le classeur complet, avec toutes les formules et le corrigé, se trouve dans l'espace enseignant, page Repères.</p></div>`;}
function leconsMd(){return "# Atelier Zéphyr : leçons\n\nCas fictif. Tous les chiffres sont des hypothèses pédagogiques.\n\n"+LECONS.map((L,i)=>`## ${i+1}. ${L.t} (${L.niv})\n\n${L.intro.join("\n\n")}\n\n### À retenir\n\n${L.points.map(p=>"- "+p).join("\n")}\n\n${L.formules.length?"### Formules\n\n"+L.formules.map(f=>`- ${f[0]} = ${f[1]}`).join("\n")+"\n\n":""}### Exemple pas à pas : ${L.ex.t}\n\n${L.ex.steps.map((p,k)=>`${k+1}. ${p}`).join("\n")}\n\n### Exercices\n\n${L.qs.map((q,k)=>`${k+1}. ${q.q}${q.choix?"\n"+q.choix.map(c=>"   - "+c).join("\n"):""}\n   Réponse : ${q.choix?q.choix[q.a]+". ":""}${q.expl}`).join("\n")}\n`).join("\n");}
async function telecharger(k){let nom,data;if(k==="lecons"){nom="atelier-zephyr-lecons.md";data=leconsMd();}else{const f=FICHIERS[k];nom=f.nom;const b=atob(f.b64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);data=new Blob([u]);}
  try{const dl=window.claude&&window.claude.use?await window.claude.use("downloads"):null;if(!dl){dlMsg="Le téléchargement n'est pas disponible dans cet affichage. Ouvrez la page dans claude.ai.";}else{await dl.save({filename:nom,data});dlMsg="Fichier enregistré : "+nom+".";}}
  catch(e){dlMsg=e&&e.code==="declined"?"Téléchargement annulé.":"Le téléchargement n'a pas abouti. Réessayez dans un instant.";}render();}

/* ---------- manuel, texte parlé, formules Excel ---------- */
let tStep=0;
const TEXTE=[["Étape 1","20 s","Vous dirigez une start-up qui conçoit des drones pour inspecter les toits et les ponts sans échafaudage. Votre première décision porte sur le prix de vente, qui est de 6 000 € par drone."],["Étape 2","30 s","Ce prix vous coûte 3 100 € à fabriquer. Chaque drone vendu vous laisse donc 2 900 € pour payer les charges fixes : salaires, loyer, assurance."],["Étape 3","30 s","Vos charges fixes de l'année sont de 650 000 €. Combien faut-il vendre de drones pour ne plus perdre d'argent ? Calculez : 650 000 ÷ 2 900. La réponse est 225 drones."],["Étape 4","30 s","Vous décidez maintenant d'un effort commercial. Plus vous en mettez, plus vous vendez, mais plus vos charges augmentent. Observez le résultat à l'écran avant de valider."],["Étape 5","30 s","Votre résultat apparaît. Si vous avez vendu 80 drones, votre marge est de 232 000 €, et votre résultat est de moins 418 000 €. C'est normal la première année."],["Étape 6","30 s","Pour l'année 2, la R&D que vous payez aujourd'hui agira demain. Ses effets s'additionnent d'une année sur l'autre."],["Étape 7","20 s","Rédigez maintenant votre réponse à la première question : pourquoi ce prix ? Citez le segment de clients que vous visez."]];
function vManuel(){return `<div class="panel lecon"><h2>Manuel d'utilisation</h2><h3>1. À quoi sert cet atelier</h3><p>Vous dirigez une start-up qui conçoit des drones d'inspection pour les chantiers. Pendant l'atelier, vous prenez des décisions chaque année : prix, effort commercial, recherche et développement. L'application calcule le chiffre d'affaires, le résultat et la trésorerie, puis vous montre ce que vos choix ont produit.</p><h3>2. Ce que vous voyez à l'écran</h3><ul><li>Les modes, en haut : le cas, les leçons, la simulation.</li><li>Les pages, sous les modes : chaque page répond à une étape de la démarche.</li><li>Les chiffres sont arrondis à l'euro près dans le parcours DU PaRéO, et à deux décimales dans le parcours DSCG.</li></ul><h3>3. Le parcours conseillé</h3><ol><li>Lire le cas et le business model.</li><li>Suivre la leçon « Chiffre d'affaires, coûts et marge ».</li><li>Choisir un prix et un budget de commercial et de R&amp;D pour l'année 1.</li><li>Observer le résultat, puis calculer le seuil de rentabilité.</li><li>Recommencer pour l'année 2 en tenant compte des effets de l'année 1.</li><li>Répondre aux trois questions annuelles et rédiger le bilan.</li></ol><h3>4. Comment lire un résultat</h3><p>Un résultat négatif n'est pas un échec en soi : la première année, les charges fixes sont élevées et les ventes sont faibles. Ce qui compte est de comprendre pourquoi le résultat est négatif et ce qu'il faudrait changer.</p><h3>5. En cas de doute</h3><p>Reprenez la leçon correspondante. Chaque leçon propose un exemple pas à pas et des exercices corrigés. La section « Formules Excel » montre comment reproduire les calculs dans un tableur.</p></div>`;}
function vTexte(){const e=TEXTE[tStep];return `<div class="panel big"><div class="row" style="justify-content:space-between"><h2>Texte parlé : ${e[0]} sur ${TEXTE.length}</h2><span class="chip">environ ${e[1]}</span></div><p class="lead">${e[2]}</p><div class="row"><button id="t-prev" ${tStep===0?"disabled":""}>Précédente</button><button class="pri" id="t-next" ${tStep===TEXTE.length-1?"disabled":""}>Étape suivante</button></div><p class="note">Le professeur lit ce texte, ou le fait afficher étape par étape à l'écran.</p></div>`;}
function vExcel(){return `<div class="panel"><h2>Formules Excel : parcours DU PaRéO</h2><p class="note">Exemple : 100 drones vendus à 6 000 €, coût variable de 3 100 € par drone. Saisissez les données dans les cellules B2 à B4, puis les formules en colonne D. Arrondi : nombre sans décimale.</p><div class="scroll"><table class="txt"><thead><tr><th>Cellule</th><th>Contenu</th><th>Formule à saisir</th><th>Résultat attendu</th></tr></thead><tbody><tr><td>B2</td><td>Ventes (drones)</td><td>100</td><td>100</td></tr><tr><td>B3</td><td>Prix de vente (€)</td><td>6000</td><td>6 000</td></tr><tr><td>B4</td><td>Coût variable par drone (€)</td><td>3100</td><td>3 100</td></tr><tr><td>D2</td><td>Chiffre d'affaires</td><td>=B2*B3</td><td>600 000</td></tr><tr><td>D3</td><td>Coûts variables</td><td>=B2*B4</td><td>310 000</td></tr><tr><td>D4</td><td>Marge sur coût variable</td><td>=D2-D3</td><td>290 000</td></tr><tr><td>D5</td><td>Taux de marge (format %, 0 décimale)</td><td>=D4/D2</td><td>48 %</td></tr><tr><td>D6</td><td>Seuil de rentabilité (charges 650 000 €)</td><td>=ARRONDI.SUP(650000/(B3-B4);0)</td><td>225</td></tr></tbody></table></div><p class="note">Fonctions utiles : SOMME, ARRONDI.SUP, SI. Pour une marge par drone, ne pas oublier les parenthèses.</p></div><div class="panel"><h2>Formules Excel : parcours DSCG</h2><p class="note">Exemple : standard 3 kg à 80 € par produit, 100 produits, réel 320 kg à 85 €. Format : deux décimales. Écart = réel − prévu : un écart positif sur un coût est défavorable.</p><div class="scroll"><table class="txt"><thead><tr><th>Cellule</th><th>Contenu</th><th>Formule à saisir</th><th>Résultat attendu</th></tr></thead><tbody><tr><td>B2</td><td>Quantité standard par produit (kg)</td><td>3</td><td>3,00</td></tr><tr><td>B3</td><td>Prix standard (€ le kg)</td><td>80</td><td>80,00</td></tr><tr><td>B4</td><td>Produits fabriqués</td><td>100</td><td>100,00</td></tr><tr><td>B5</td><td>Quantité réelle (kg)</td><td>320</td><td>320,00</td></tr><tr><td>B6</td><td>Prix réel (€ le kg)</td><td>85</td><td>85,00</td></tr><tr><td>D2</td><td>Coût standard de la production réelle (€)</td><td>=B2*B4*B3</td><td>24 000,00</td></tr><tr><td>D3</td><td>Coût réel (€)</td><td>=B5*B6</td><td>27 200,00</td></tr><tr><td>D4</td><td>Écart total (€)</td><td>=D3-D2</td><td>3 200,00</td></tr><tr><td>D5</td><td>Écart sur quantité (€)</td><td>=(B5-B2*B4)*B3</td><td>1 600,00</td></tr><tr><td>D6</td><td>Écart sur prix (€)</td><td>=(B6-B3)*B5</td><td>1 600,00</td></tr><tr><td>D7</td><td>Contrôle : quantité + prix − total</td><td>=D5+D6-D4</td><td>0,00</td></tr><tr><td>D8</td><td>Sens de l'écart</td><td>=SI(D4&gt;0;"Défavorable";"Favorable")</td><td>Défavorable</td></tr></tbody></table></div><p class="note">Fonctions utiles : SI, ARRONDI(…;2) pour les décimales. Recopiez les formules vers le bas pour traiter plusieurs produits.</p></div>`;}


/* ---------- Découvrir, version DSCG : l'entreprise à son troisième exercice ---------- */
const BLOCS_DS={1:"Deux modèles : le Z1 pour l'inspection courante, le Z2 haut de gamme à capteur thermique",4:"Vente des drones : Z1 à 6 000 € et Z2 à 9 000 € au budget",5:"Équipe de conception, logiciel embarqué, atelier d'assemblage de 7 200 heures d'activité normale",8:"Coût standard de production (fibre, kit, main-d'œuvre, charges d'atelier) et 1 750 000 € de charges de structure budgétées"};
const RESS_DS=[["Équipe de conception","A conçu un second modèle en trois ans. La reprise du capteur thermique a retardé le Z2 de trois mois.","Force fragile"],["Logiciel embarqué","Commun aux deux modèles. Reste l'avantage principal face aux fabricants généralistes.","Force"],["Atelier d'assemblage","Activité normale de 7 200 heures. Deux assembleurs expérimentés sont partis en cours d'exercice.","Point de vigilance"],["Réseau commercial","Construit depuis le lancement. A tenu les volumes du Z1 en accordant des remises.","Force coûteuse"],["Achats","Peu de fournisseurs pour la fibre et les kits. Un nouveau fournisseur a été retenu pour le kit Z2.","Dépendance"],["Finances","Premier bénéfice annoncé aux investisseurs pour cet exercice. Le contrôle de gestion repose sur des standards vieux d'un an.","Point de vigilance"]];
const NOTIONS_DS=[["Coût standard","Un coût fixé à l'avance pour une unité produite, à partir de quantités et de prix jugés normaux. Il sert de référence pour mesurer les écarts."],["Unité d'œuvre","L'unité qui sert à répartir les charges indirectes d'un centre entre les produits. Ici : l'heure de main-d'œuvre directe."],["Activité normale","Le niveau d'activité retenu pour calculer le coût de l'unité d'œuvre. Ici : celui du programme de ventes budgété."],["Budget flexible","Le budget d'un centre recalculé pour l'activité réellement constatée : charges fixes + coût variable unitaire × activité réelle."],["Marge standard","Prix de vente budgété moins coût standard de production. Elle isole la performance commerciale de celle de l'atelier."],["Écart sur marge","Marge réelle évaluée au coût standard moins marge budgétée. Il se décompose en prix, volume global et composition."],["Écart de composition","L'effet d'un déplacement des ventes vers des produits plus ou moins margeants, à volume total donné."],["Écart sur rendement","Le coût des unités d'œuvre consommées en plus ou en moins du standard pour la production obtenue."],["Charges de structure","Conception, commercial, administration : elles ne sont pas incorporées au coût de production et sont suivies à part."],["Tableau de passage","La liste des écarts qui mène du résultat budgété au résultat réel. La somme doit boucler exactement."]];
function vCasDs(){const M=["Z1","Z2"],us={Z1:"Inspection courante de toitures et de façades",Z2:"Haut de gamme à capteur thermique, pour les ouvrages"};
  return `<div class="panel"><h2>Atelier Zéphyr, troisième exercice</h2><p class="lead">Trois ans après sa création, la start-up vend deux modèles de drones d'inspection. La direction avait annoncé aux investisseurs un premier bénéfice. L'exercice se clôt en perte, alors que le nombre total de drones vendus est exactement celui du budget.</p>
  <div class="grid"><div class="fact"><b>2 modèles</b><span>Z1 et Z2</span></div><div class="fact"><b>600 drones</b><span>prévus au budget, et 600 vendus</span></div><div class="fact"><b>${num(DS.r.h)} h</b><span>de main-d'œuvre directe réelles</span></div><div class="fact"><b>${eur(DS.strB)}</b><span>de charges de structure budgétées</span></div></div></div>
  <div class="panel"><h2>Les deux modèles</h2><div class="scroll"><table><thead><tr><th>Modèle</th><th>Usage</th><th>Quantité budgétée</th><th>Quantité vendue</th><th>Prix budgété</th><th>Prix réel moyen</th></tr></thead><tbody>${M.map(m=>`<tr><td><b>${m}</b></td><td style="text-align:left;white-space:normal">${us[m]}</td><td>${DS.bud[m].q}</td><td${neg(DS.reel[m].q-DS.bud[m].q)}>${DS.reel[m].q}</td><td>${eur(DS.bud[m].p)}</td><td${neg(DS.reel[m].p-DS.bud[m].p)}>${eur(DS.reel[m].p)}</td></tr>`).join("")}</tbody></table></div><p class="note">En rouge : ce qui est inférieur au budget. Les standards de production et les coûts réels sont dans « Sujet et annexes ».</p></div>
  <div class="panel"><h2>Ce qui s'est passé pendant l'exercice</h2><ul>${INFOS.map(x=>`<li>${x}</li>`).join("")}</ul></div>
  <div class="panel"><h2>Votre mission de contrôleurs de gestion</h2><ol><li>Reconstituer les standards et le résultat budgété. <a href="#sujet">Sujet et annexes</a></li><li>Calculer les 27 valeurs : écart de résultat, écart sur marge, écarts sur coûts directs et sur charges indirectes. <a href="#ecarts">Calcul des écarts</a></li><li>Expliquer le passage du résultat budgété au résultat réel. <a href="#passage">Tableau de passage</a></li><li>Rédiger le diagnostic, proposer des actions et discuter les limites de la méthode. <a href="#diagnostic">Diagnostic</a></li><li>Faire le point avant la soutenance. <a href="#bilan">Bilan du projet</a></li></ol><p class="note">Ce cas reprend l'entreprise de la simulation DU PaRéO trois ans plus tard, avec des données plus détaillées. Les deux jeux de chiffres sont indépendants.</p></div>`;}
function vCanevasDs(){return `<div class="panel"><h2>Le business model au troisième exercice</h2><p class="note">Les blocs marqués « mis à jour » ont changé depuis le lancement. Ils expliquent une partie des écarts : deux produits au lieu d'un, donc un risque de composition des ventes.</p><div class="canvas">${BLOCS.map((b,i)=>`<div><h3>${b[0]}${BLOCS_DS[i]?' <span class="chip wait">mis à jour</span>':""}</h3><p>${BLOCS_DS[i]||b[1]}</p></div>`).join("")}</div><p><b>À discuter :</b> quel bloc du modèle est à l'origine de l'écart le plus lourd ?</p></div>`;}
function vEnvDs(){const lien=[["Clients et concurrents","Un concurrent est entré sur le segment du Z1 ; les remises ont tenu les volumes.","Écart sur prix du Z1"],["Conception","Le Z2 a été livré avec trois mois de retard.","Écart de composition des ventes"],["Fournisseurs","Hausse du tarif de la fibre ; nouveau fournisseur pour le kit Z2.","Écarts sur prix des matières et des kits"],["Emploi","Deux assembleurs expérimentés remplacés par des débutants.","Écarts sur temps, sur rendement et sur quantité de fibre"]];
  return `<div class="panel"><h2>De l'environnement aux écarts</h2><p class="note">Chaque fait de l'exercice se retrouve dans un écart. C'est le lien à établir dans le diagnostic.</p>${liste3(lien,["Domaine","Fait de l'exercice 3","Écart à examiner"])}</div><div class="panel"><h2>Macro-environnement</h2>${liste3(MACRO,["Domaine","Constat","Effet"])}</div><div class="panel"><h2>Micro-environnement</h2>${liste3(MICRO,["Acteur","Constat","Intensité"])}</div>`;}
function vRessDs(){return `<div class="panel"><h2>Ressources et compétences au troisième exercice</h2><p class="note">Une ressource fragilisée se lit dans les écarts de l'exercice.</p>${liste3(RESS_DS,["Ressource","Constat","Diagnostic"])}<p><b>À discuter :</b> quelles ressources faut-il sécuriser en premier, et quel indicateur mensuel aurait donné l'alerte ?</p></div>`;}
function vMarcheDs(){const b=DS.bud,r=DS.reel,pt=(q,t)=>Math.round(q*100/t);
  return `<div class="panel"><h2>Composition des ventes : budget et réel</h2><div class="scroll"><table><thead><tr><th>Modèle</th><th>Quantité budgétée</th><th>Part au budget</th><th>Quantité vendue</th><th>Part réelle</th></tr></thead><tbody>${["Z1","Z2"].map(m=>`<tr><td><b>${m}</b></td><td>${b[m].q}</td><td>${pt(b[m].q,600)} %</td><td>${r[m].q}</td><td>${pt(r[m].q,600)} %</td></tr>`).join("")}<tr class="tot"><td>Total</td><td>600</td><td>100 %</td><td>600</td><td>100 %</td></tr></tbody></table></div>${bars(["Z1 budget","Z1 réel","Z2 budget","Z2 réel"],[b.Z1.q,r.Z1.q,b.Z2.q,r.Z2.q],{label:"Quantités par modèle, budget et réel",fmt:v=>num(v)+" drones"})}<p class="note">Le volume total est tenu, mais la part du Z2 recule. L'effet de ce déplacement sur la marge est l'écart de composition.</p></div>
  <div class="panel"><h2>Les segments de clients</h2><div class="scroll"><table class="txt"><thead><tr><th>Segment</th><th>Modèle acheté</th><th>Comportement d'achat</th></tr></thead><tbody><tr><td><b>Entreprises de couverture</b></td><td>Z1</td><td>Très sensibles au prix : c'est sur ce segment que le concurrent est entré.</td></tr><tr><td><b>Bureaux de contrôle</b></td><td>Z1 et Z2</td><td>Achètent pour la précision des mesures. Peu sensibles au prix.</td></tr><tr><td><b>Gestionnaires d'ouvrages</b></td><td>Z2</td><td>Achètent par appel d'offres. Un retard de livraison fait perdre la commande.</td></tr></tbody></table></div></div>
  <div class="panel"><h2>SWOT</h2><div class="swot">${Object.keys(SWOT).map(k=>`<div><h3>${k}</h3><ul>${SWOT[k].map(x=>`<li>${x}</li>`).join("")}</ul></div>`).join("")}</div></div>`;}

/* ---------- mode Découvrir ---------- */
const liste3=(rows,h)=>`<div class="scroll"><table class="txt"><thead><tr>${h.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td><span class="chip">${r[2]}</span></td></tr>`).join("")}</tbody></table></div>`;
function vCas(){if(PARC==="dscg")return vCasDs();return `<div class="panel"><h2>Atelier Zéphyr</h2><p class="lead">Trois associés ingénieurs créent une start-up qui conçoit un drone d'inspection pour les bâtiments et les ouvrages : toitures, façades, ponts. Ils partent avec 500 000 € et trois ans pour atteindre la rentabilité.</p>
  <div class="grid"><div class="fact"><b>500 000 €</b><span>trésorerie de départ</span></div><div class="fact"><b>6 000 €</b><span>prix de base du drone</span></div><div class="fact"><b>3 100 €</b><span>coût variable par drone</span></div><div class="fact"><b>80 → 500</b><span>drones : demande de base, de l'an 1 à l'an 3</span></div></div></div>
  <div class="panel"><h2>Votre mission</h2><ol><li>Comprendre l'entreprise : son business model, son environnement, ses forces et ses faiblesses.</li><li>Diriger l'entreprise pendant trois ans : chaque année, fixer un prix, un effort commercial et un budget de recherche.</li><li>Calculer vous-mêmes vos ventes, votre résultat et votre trésorerie, puis les vérifier.</li><li>En année 2, convaincre un investisseur en trois minutes.</li><li>Au bilan, expliquer vos choix et ce que vous feriez en année 4.</li></ol></div>
  <div class="panel"><h2>Les trois années</h2><div class="scroll"><table><thead><tr><th>Année</th><th>Demande de base</th><th>Charges fixes</th><th>Apport</th></tr></thead><tbody>${[0,1,2].map(y=>`<tr><td>${y+1} · ${TITRES[y]}</td><td>${num(PR().dem[y])} drones</td><td>${eur(PR().fix[y])}</td><td>${y===1?eur(PR().app[1])+" (levée de fonds)":y===0?"500 000 € au départ":"aucun"}</td></tr>`).join("")}</tbody></table></div></div>`;}
function vCanevas(){if(PARC==="dscg")return vCanevasDs();if(!S.teams.length)return vide();const t=team();return `<div class="panel"><div class="row" style="justify-content:space-between"><h2>Le business model en neuf blocs</h2>${selEq()}</div><p class="note">Le texte proposé est un point de départ. Chaque équipe écrit sa propre version, et la révise à chaque année. La saisie est enregistrée dès que vous quittez la case.</p>
  <div class="canvas">${BLOCS.map((b,i)=>`<div><h3>${b[0]}</h3><p class="note">${b[1]}</p><textarea id="cv-${i}" data-cv="${i}" aria-label="${b[0]} : version de l'équipe" placeholder="Votre version">${esc(t.cv[i]||"")}</textarea></div>`).join("")}</div>
  <p><b>Question de départ :</b> quel bloc est le plus fragile, et pourquoi ?</p></div>`;}
function vEnv(){if(PARC==="dscg")return vEnvDs();return `<div class="panel"><h2>Macro-environnement</h2><p class="note">Ce qui entoure l'entreprise et qu'elle ne contrôle pas. Situation imaginée pour le cas.</p>${liste3(MACRO,["Domaine","Constat","Effet"])}</div>
  <div class="panel"><h2>Micro-environnement</h2><p class="note">Les acteurs avec lesquels l'entreprise traite tous les jours.</p>${liste3(MICRO,["Acteur","Constat","Intensité"])}</div>`;}
function vRess(){if(PARC==="dscg")return vRessDs();return `<div class="panel"><h2>Ressources et compétences</h2><p class="note">Ce que l'entreprise possède et sait faire. Une force rare et difficile à copier est un avantage durable.</p>${liste3(RESS,["Ressource","Constat","Diagnostic"])}<p><b>À discuter :</b> quelle faiblesse faut-il corriger en premier, et avec quelle décision du jeu ?</p></div>`;}
function vMarche(){if(PARC==="dscg")return vMarcheDs();const p=PR();return `<div class="panel"><h2>Les segments de clients</h2><div class="scroll"><table class="txt"><thead><tr><th>Segment</th><th>Part de la demande</th><th>Comportement d'achat</th></tr></thead><tbody>${SEGMENTS.map(s=>`<tr><td><b>${s[0]}</b></td><td><div class="jauge"><i style="width:${s[1]}%"></i></div>${s[1]} %</td><td>${s[2]}</td></tr>`).join("")}</tbody></table></div>
  <p class="note">Un prix bas attire les entreprises de couverture ; un prix haut vise les bureaux de contrôle. C'est ce que traduisent les coefficients de prix du jeu.</p>${bars(["Année 1","Année 2","Année 3"],p.dem,{label:"Demande de base par année",fmt:v=>num(v)+" drones"})}</div>
  <div class="panel"><h2>SWOT</h2><div class="swot">${Object.keys(SWOT).map(k=>`<div><h3>${k}</h3><ul>${SWOT[k].map(x=>`<li>${x}</li>`).join("")}</ul></div>`).join("")}</div></div>`;}
function vNotions(){return `<div class="panel"><h2>Les notions du cours</h2><dl class="gloss">${(PARC==="dscg"?NOTIONS_DS:NOTIONS).map(n=>`<div><dt>${n[0]}</dt><dd>${n[1]}</dd></div>`).join("")}</dl></div>`;}

/* ---------- mode Simuler ---------- */
let timer={left:1200,run:false,id:null};
const fmtT=()=>String(Math.floor(timer.left/60)).padStart(2,"0")+":"+String(timer.left%60).padStart(2,"0");
function tick(){if(timer.left>0)timer.left--;else{timer.run=false;clearInterval(timer.id);}const el=document.getElementById("timer");if(el){el.textContent=fmtT();el.classList.toggle("end",timer.left===0);}}
function faits(y){const p=PR();return `<div class="grid"><div class="fact"><b>${num(p.dem[y])}</b><span>drones : demande de base</span></div><div class="fact"><b>${eur(p.fix[y])}</b><span>charges fixes de l'année</span></div><div class="fact"><b>${eur(p.cv[y])}</b><span>coût variable par drone</span></div><div class="fact"><b>${y===1?eur(p.app[1]):"aucun"}</b><span>apport de trésorerie${y===1?" (levée de fonds)":""}</span></div></div>${S.ev?`<p class="banner"><b>Événement de l'année : ${EVTS[y].t}.</b> ${EVTS[y].d}</p>`:""}`;}
function tabRes(y){const rows=S.teams.map((t,i)=>{const r=calc(t),a=r[y];if(!a)return "";const cum=r.slice(0,y+1).reduce((s,o)=>s+o.res,0),al=r.slice(0,y+1).some(o=>o.fin<0),d=t.d[y];
    return `<tr><td><span class="dot" style="background:${col(i)}"></span> ${esc(t.n)}</td><td>${eur(a.prix)}</td><td>${num(a.com/1000)} k€</td><td>${num(a.rd/1000)} k€</td><td>${num(a.v)}</td><td>${eur(a.ca)}</td><td${neg(a.res)}>${eur(a.res)}</td><td${neg(a.fin)}>${eur(a.fin)}</td><td${neg(cum)}>${eur(cum)}</td><td>${al?'<span class="chip ko">alerte banque</span>':'<span class="chip ok">tenue</span>'}</td></tr>`;}).join("");
  return `<div class="scroll"><table><thead><tr><th>Équipe</th><th>Prix</th><th>Commercial</th><th>R&amp;D</th><th>Ventes</th><th>Chiffre d'affaires</th><th>Résultat</th><th>Trésorerie fin</th><th>Résultat cumulé</th><th>Banque</th></tr></thead><tbody>${rows}</tbody></table></div>`;}
function vClasse(){const y=annee(),dc=dClos();let h=S.exemple?`<p class="banner">Partie d'exemple : trois équipes fictives, année 1 clôturée. Lancez une nouvelle partie dans le mode Enseignant, page Sauvegarde.</p>`:"";
  if(y<3)h+=`<div class="panel big"><div class="row" style="justify-content:space-between"><h2>Année ${y+1} · ${TITRES[y]}</h2><div class="row"><span class="timer${timer.left===0?" end":""}" id="timer">${fmtT()}</span><button id="t-go">${timer.run?"Pause":"Démarrer"}</button><button id="t-20">20 min</button><button id="t-10">10 min</button></div></div>${faits(y)}
    <div class="row">${S.teams.map(t=>`<span class="chip ${t.d[y]?"ok":"wait"}">${esc(t.n)} : ${t.d[y]?"a décidé":"en attente"}</span>`).join("")}</div><p class="note">Chaque équipe choisit un prix, un effort commercial et un budget de R&amp;D, puis calcule ses ventes, son résultat et sa trésorerie. Les décisions restent cachées jusqu'à la clôture de l'année.</p></div>`;
  else h+=`<div class="panel big"><h2>Les trois années sont jouées</h2><p class="note">Chaque équipe présente son bilan : ce qu'elle a décidé, pourquoi, et ce qui se passerait en année 4.</p></div>`;
  if(dc>=0){const v=Math.max(0,Math.min(S.sel==null?dc:S.sel,dc));h+=`<div class="panel big"><div class="row" style="justify-content:space-between"><h2>Résultats de l'année ${v+1}</h2><div class="seg">${[0,1,2].filter(i=>i<=dc).map(i=>`<button data-sel="${i}" aria-pressed="${i===v}">Année ${i+1}</button>`).join("")}</div></div>${tabRes(v)}</div><div class="panel"><h2>Trésorerie des équipes</h2>${courbe()}</div>`;}
  return h;}
const seg=(k,list,cur,lab)=>`<div class="seg">${list.map((o,i)=>`<button data-dec="${k}" data-i="${i}" aria-pressed="${cur===i}">${lab(o)}</button>`).join("")}</div>`;
function vDecisions(){if(!S.teams.length)return vide();const y=annee(),t=team(),p=PR();let h=`<div class="panel"><div class="row">${selEq()}</div>`;
  if(y>2)return h+`<p>Les trois années sont clôturées. Les résultats sont sur l'écran de classe et dans le tableau de bord.</p></div>`;
  const prev=simul(t.d.slice(0,y),p),deb=y?prev[y-1].fin:p.t0,bonus=t.d.slice(0,y).reduce((s,d)=>s+p.R[d.r].b,0),d=(t._p&&t._p.y===y?t._p:t.d[y])||{},s=t.s[y]||{};
  h+=`<h2>Année ${y+1} · ${TITRES[y]}</h2>${faits(y)}<div class="grid"><div class="fact"><b>${eur(deb)}</b><span>trésorerie de début d'année</span></div><div class="fact"><b>+${bonus} %</b><span>bonus de R&amp;D déjà acquis</span></div></div></div>
  <div class="panel"><h3>1. Les trois décisions</h3><label>Prix de vente${seg("p",p.P,d.p,o=>`${num(o.v)} €<small>coefficient ${coef(o.k[y])}</small>`)}</label><label>Effort commercial${seg("c",p.C,d.c,o=>`${num(o.v)} €<small>coefficient ${coef(o.k)}</small>`)}</label><label>Recherche et développement${seg("r",p.R,d.r,o=>`${num(o.v)} €<small>${o.b?"+"+o.b+" % dès l'an prochain":"aucun effet"}</small>`)}</label>
  <span class="chip ${t.d[y]?"ok":"wait"}">${t.d[y]?"Décision enregistrée, modifiable jusqu'à la clôture":"Choisissez les trois niveaux pour enregistrer la décision"}</span></div>
  <div class="panel"><h3>2. Le calcul à la main</h3><p class="note">Calculez sur papier, puis saisissez vos quatre résultats. La page dit seulement s'ils sont justes.</p><div class="grid">${[["v","Ventes (drones)"],["ca","Chiffre d'affaires (€)"],["res","Résultat (€)"],["fin","Trésorerie de fin (€)"]].map(([k,l])=>`<label>${l}<input id="in-${k}" inputmode="numeric" value="${esc(s[k]||"")}"><span class="check ${s["ok"+k]===true?"ok":s["ok"+k]===false?"ko":""}">${s["ok"+k]===true?"Juste":s["ok"+k]===false?"À revoir":"&nbsp;"}</span></label>`).join("")}</div>
  <div class="row"><button class="pri" id="verif" ${t.d[y]?"":"disabled"}>Vérifier mes calculs</button><span class="note">${s.essais?s.essais+" vérification"+(s.essais>1?"s":""):""}</span></div></div>
  <div class="panel"><h3>3. Justifier</h3>${QJUST.map((q,i)=>`<label>${q}<textarea id="j-${y}-${i}" data-j="${y}-${i}">${esc((t.j[y]||[])[i]||"")}</textarea></label>`).join("")}</div>`;return h;}
let theme="commercial";
function vBord(){if(!S.teams.length)return vide();const t=team(),n=dClos()+1,r=calc(t).slice(0,n),p=PR();
  let h=`<div class="panel"><div class="row" style="justify-content:space-between"><h2>Tableau de bord</h2>${selEq()}</div><div class="seg">${[["commercial","Commercial"],["finances","Compte de résultat"],["tresorerie","Trésorerie et bilan"]].map(([k,l])=>`<button data-theme="${k}" aria-pressed="${theme===k}">${l}</button>`).join("")}</div>`;
  if(!r.length)return h+`<p>Aucune année clôturée pour le moment. Le tableau de bord se remplit à la clôture de chaque année.</p></div>`;
  const L=r.map((_,i)=>"Année "+(i+1)),last=r[r.length-1],y=r.length-1,tot=S.teams.reduce((s,o)=>{const a=calc(o)[y];return s+(a?a.v:0);},0),cum=r.reduce((s,o)=>s+o.res,0);
  const ligne=(l,f,c)=>`<tr${c?` class="${c}"`:""}><td>${l}</td>${r.map(a=>{const v=f(a);return typeof v==="number"?`<td${neg(v)}>${eur(v)}</td>`:`<td>${v}</td>`;}).join("")}</tr>`,th=`<thead><tr><th></th>${L.map(l=>`<th>${l}</th>`).join("")}</tr></thead>`;
  if(theme==="commercial")h+=`<div class="grid"><div class="fact"><b>${num(last.v)}</b><span>drones vendus en année ${y+1}</span></div><div class="fact"><b>${eur(last.ca)}</b><span>chiffre d'affaires</span></div><div class="fact"><b>${tot?Math.round(last.v*100/tot):0} %</b><span>part des ventes de la classe</span></div><div class="fact"><b>${num(last.seuil)}</b><span>drones : seuil de rentabilité</span></div></div></div>
    <div class="panel"><h3>Ventes par année</h3>${bars(L,r.map(a=>a.v),{label:"Ventes par année"})}<div class="scroll"><table>${th}<tbody>${ligne("Prix de vente",a=>eur(a.prix))}${ligne("Demande de base",(a)=>num(p.dem[r.indexOf(a)]))}${ligne("Ventes (drones)",a=>num(a.v))}${ligne("Seuil de rentabilité (drones)",a=>num(a.seuil))}${ligne("Écart au seuil (drones)",a=>`<span${neg(a.v-a.seuil)}>${sig(a.v-a.seuil)}</span>`)}</tbody></table></div><p class="note">Seuil de rentabilité : charges de l'année ÷ marge sur coût variable par drone. Sous le seuil, l'année est en perte.</p></div>`;
  else if(theme==="finances")h+=`<div class="grid"><div class="fact"><b${neg(last.res)}>${eur(last.res)}</b><span>résultat de l'année ${y+1}</span></div><div class="fact"><b${neg(cum)}>${eur(cum)}</b><span>résultat cumulé</span></div><div class="fact"><b>${String(last.tmcv).replace(".",",")} %</b><span>taux de marge sur coût variable</span></div></div></div>
    <div class="panel"><h3>Compte de résultat</h3><div class="scroll"><table>${th}<tbody>${ligne("Chiffre d'affaires",a=>a.ca)}${ligne("− Coûts variables",a=>a.cvt)}${ligne("= Marge sur coût variable",a=>a.mcv,"tot")}${ligne("− Charges fixes",a=>a.fix)}${ligne("− Effort commercial",a=>a.com)}${ligne("− Recherche et développement",a=>a.rd)}${ligne("= Résultat",a=>a.res,"tot")}</tbody></table></div>${bars(L,r.map(a=>a.res/1000),{label:"Résultat par année",fmt:v=>sig(Math.round(v))+" k€"})}</div>`;
  else{const app=p.t0+r.reduce((s,a)=>s+a.app,0);h+=`<div class="grid"><div class="fact"><b${neg(last.fin)}>${eur(last.fin)}</b><span>trésorerie fin d'année ${y+1}</span></div><div class="fact"><b>${last.fin>0?String(last.auto).replace(".",",")+" mois":"aucune"}</b><span>autonomie au rythme des charges de l'année</span></div><div class="fact"><b>${r.some(a=>a.fin<0)?"Alerte":"Tenue"}</b><span>situation à la banque</span></div></div></div>
    <div class="panel"><h3>Plan de trésorerie</h3><div class="scroll"><table>${th}<tbody>${ligne("Trésorerie de début",a=>a.deb)}${ligne("+ Encaissements des ventes",a=>a.ca)}${ligne("− Décaissements",a=>a.cvt+a.ch)}${ligne("+ Apport des investisseurs",a=>a.app)}${ligne("= Trésorerie de fin",a=>a.fin,"tot")}</tbody></table></div></div>
    <div class="panel"><h3>Bilan simplifié en fin d'année ${y+1}</h3><div class="grid2"><div class="scroll"><table><thead><tr><th>Actif</th><th></th></tr></thead><tbody><tr><td>Trésorerie</td><td>${eur(Math.max(last.fin,0))}</td></tr><tr class="tot"><td>Total</td><td>${eur(Math.max(last.fin,0))}</td></tr></tbody></table></div>
    <div class="scroll"><table><thead><tr><th>Passif</th><th></th></tr></thead><tbody><tr><td>Apports des associés et investisseurs</td><td>${eur(app)}</td></tr><tr><td>Résultats cumulés</td><td${neg(cum)}>${eur(cum)}</td></tr>${last.fin<0?`<tr><td>Découvert bancaire</td><td>${eur(-last.fin)}</td></tr>`:""}<tr class="tot"><td>Total</td><td>${eur(Math.max(last.fin,0))}</td></tr></tbody></table></div></div><p class="note">Le bilan est réduit à l'essentiel : l'entreprise n'a ici ni stock, ni créances, ni dettes fournisseurs, ni matériel.</p></div>`;}
  return h;}
const INDIC=[["v","Ventes (drones)","Commercial",num],["ca","Chiffre d'affaires","Commercial",eur],["seuil","Seuil de rentabilité (drones)","Commercial",num],["mcv","Marge sur coût variable","Finances",eur],["tmcv","Taux de marge sur coût variable (%)","Finances",v=>String(v).replace(".",",")],["res","Résultat","Finances",eur],["cum","Résultat cumulé","Finances",eur],["fin","Trésorerie de fin","Trésorerie",eur],["auto","Autonomie (mois)","Trésorerie",v=>String(v).replace(".",",")]];
let filtre="Tous";
function vDetail(){const n=dClos()+1;let h=`<div class="panel"><h2>Tableau détaillé par indicateur</h2><div class="seg">${["Tous","Commercial","Finances","Trésorerie"].map(f=>`<button data-filtre="${f}" aria-pressed="${filtre===f}">${f}</button>`).join("")}</div>`;
  if(n<1)return h+`<p>Aucune année clôturée pour le moment.</p></div>`;
  const data=S.teams.map(t=>{let c=0;return calc(t).slice(0,n).map(a=>{c+=a.res;return Object.assign({cum:c},a);});});
  h+=`<div class="scroll"><table><thead><tr><th>Indicateur</th><th>Équipe</th>${Array.from({length:n},(_,i)=>`<th>Année ${i+1}</th>`).join("")}</tr></thead><tbody>${INDIC.filter(I=>filtre==="Tous"||I[2]===filtre).map(I=>S.teams.map((t,i)=>`<tr${i===0?' class="grp"':""}><td>${i===0?`<b>${I[1]}</b><br><span class="note">${I[2]}</span>`:""}</td><td style="text-align:left"><span class="dot" style="background:${col(i)}"></span> ${esc(t.n)}</td>${data[i].map(a=>`<td${neg(a[I[0]])}>${I[3](a[I[0]])}</td>`).join("")}</tr>`).join("")).join("")}</tbody></table></div></div>`;return h;}
function vRegles(){const p=PR();return `<div class="panel"><h2>Données communes</h2><div class="scroll"><table><thead><tr><th>Donnée</th><th>Année 1</th><th>Année 2</th><th>Année 3</th></tr></thead><tbody><tr><td>Demande de base (drones)</td>${p.dem.map(v=>`<td>${num(v)}</td>`).join("")}</tr><tr><td>Charges fixes</td>${p.fix.map(v=>`<td>${eur(v)}</td>`).join("")}</tr><tr><td>Coût variable par drone</td>${p.cv.map(v=>`<td>${eur(v)}</td>`).join("")}</tr><tr><td>Apport de trésorerie</td><td>${eur(p.t0)} au départ</td><td>${eur(p.app[1])}</td><td>0 €</td></tr></tbody></table></div></div>
  <div class="panel"><h2>Les trois décisions</h2><div class="scroll"><table><thead><tr><th>Décision</th><th>Choix bas</th><th>Choix moyen</th><th>Choix haut</th></tr></thead><tbody><tr><td>Prix de vente</td>${p.P.map(o=>`<td>${eur(o.v)} : coef. ${coef(o.k[0])}${o.k[2]!==o.k[0]?" ("+coef(o.k[2])+" en année 3)":""}</td>`).join("")}</tr><tr><td>Effort commercial</td>${p.C.map(o=>`<td>${eur(o.v)} : coef. ${coef(o.k)}</td>`).join("")}</tr><tr><td>R&amp;D</td>${p.R.map(o=>`<td>${eur(o.v)} : ${o.b?"+"+o.b+" %":"aucun effet"}</td>`).join("")}</tr></tbody></table></div><p class="note">La R&amp;D n'agit pas l'année où elle est payée. Elle augmente les ventes de toutes les années suivantes, et les effets s'additionnent.</p></div>
  <div class="panel"><h2>Les calculs, dans l'ordre</h2><ol><li>Ventes = demande de base × coefficient de prix × coefficient commercial × (1 + bonus de R&amp;D acquis), arrondies à l'unité la plus proche.</li><li>Chiffre d'affaires = ventes × prix.</li><li>Marge sur coût variable = ventes × (prix − coût variable).</li><li>Résultat = marge sur coût variable − charges fixes − effort commercial − R&amp;D.</li><li>Trésorerie de fin = trésorerie de début + apport éventuel + résultat.</li></ol><p class="note">Simplifications : les clients paient comptant ; ni stock, ni investissement, ni impôt, ni TVA. Une trésorerie négative met l'équipe en alerte banque : elle continue à jouer et doit expliquer comment elle aurait pu l'éviter.</p></div>`;}

