const O=dscg(),val=k=>k.split(".").reduce((a,x)=>a[x],O);
const PTS={"1. Standards":1,"2. Budget et constat":2,"3. Écart sur marge":2.5,"4. Coûts directs":2,"5. Charges indirectes":1.5,"6. Structure":1};
const AIDE={an:"quantités budgétées × temps standard de main-d'œuvre, pour les deux modèles","uo":"(charges fixes + coût variable × activité normale) ÷ activité normale","cs.Z1":"fibre + kit + main-d'œuvre + charges indirectes (temps standard × coût de l'unité d'œuvre)","cs.Z2":"fibre + kit + main-d'œuvre + charges indirectes (temps standard × coût de l'unité d'œuvre)","ms.Z1":"prix de vente budgété − coût standard de production","ms.Z2":"prix de vente budgété − coût standard de production",resB:"chiffre d'affaires budgété − coût standard de la production budgétée − charges de structure budgétées",resR:"chiffre d'affaires réel − coûts réels de production (fibre, kits, main-d'œuvre, charges indirectes) − structure réelle",eRes:"résultat réel − résultat budgété",eCA:"chiffre d'affaires réel − chiffre d'affaires budgété",eM:"marge réelle évaluée au coût standard − marge budgétée",ePrix:"(prix réel − prix budgété) × quantité réelle, modèle par modèle",eVol:"(quantité totale réelle − quantité totale budgétée) × marge moyenne budgétée",eComp:"marge standard des ventes réelles − quantité totale réelle × marge moyenne budgétée",eFib:"coût réel de la fibre − quantité standard pour la production réelle × prix standard",eFibQ:"(quantité réelle − quantité standard pour la production réelle) × prix standard",eFibP:"(prix réel − prix standard) × quantité réelle",eKit:"(prix réel − prix standard) × nombre de kits, modèle par modèle",eMod:"coût réel de la main-d'œuvre − heures standards pour la production réelle × taux standard",eModT:"(heures réelles − heures standards pour la production réelle) × taux standard",eModX:"(taux réel − taux standard) × heures réelles",bf:"charges fixes + coût variable par heure × heures réelles",eCI:"charges réelles − heures standards pour la production réelle × coût de l'unité d'œuvre",eCIb:"charges réelles − budget flexible",eCIa:"budget flexible − heures réelles × coût de l'unité d'œuvre",eCIr:"(heures réelles − heures standards) × coût de l'unité d'œuvre",eStr:"charges de structure réelles − charges de structure budgétées"};
const XLF={"an": "=D!B5*D!B13+D!C5*D!C13", "uo": "=(D!B16+D!B17*B5)/B5", "cs.Z1": "=D!B11*D!D11+D!B12+D!B13*D!D13+D!B13*B6", "cs.Z2": "=D!C11*D!D11+D!C12+D!C13*D!D13+D!C13*B6", "ms.Z1": "=D!B6-B7", "ms.Z2": "=D!C6-B8", "resB": "=D!B5*D!B6+D!C5*D!C6-D!B5*B7-D!C5*B8-D!B18", "resR": "=D!B7*D!B8+D!C7*D!C8-D!B21*D!C21-D!B7*D!B22-D!C7*D!B23-D!B24*D!C24-D!B25-D!B26", "eRes": "=B13-B12", "eCA": "=D!B7*D!B8+D!C7*D!C8-D!B5*D!B6-D!C5*D!C6", "eM": "=D!B7*(D!B8-B7)+D!C7*(D!C8-B8)-D!B5*B9-D!C5*B10", "ePrix": "=(D!B8-D!B6)*D!B7+(D!C8-D!C6)*D!C7", "eVol": "=((D!B7+D!C7)-(D!B5+D!C5))*(D!B5*B9+D!C5*B10)/(D!B5+D!C5)", "eComp": "=D!B7*B9+D!C7*B10-(D!B7+D!C7)*(D!B5*B9+D!C5*B10)/(D!B5+D!C5)", "eFib": "=D!B21*D!C21-(D!B7*D!B11+D!C7*D!C11)*D!D11", "eFibQ": "=(D!B21-(D!B7*D!B11+D!C7*D!C11))*D!D11", "eFibP": "=(D!C21-D!D11)*D!B21", "eKit": "=(D!B22-D!B12)*D!B7+(D!B23-D!C12)*D!C7", "eMod": "=D!B24*D!C24-(D!B7*D!B13+D!C7*D!C13)*D!D13", "eModT": "=(D!B24-(D!B7*D!B13+D!C7*D!C13))*D!D13", "eModX": "=(D!C24-D!D13)*D!B24", "bf": "=D!B16+D!B17*D!B24", "eCI": "=D!B25-(D!B7*D!B13+D!C7*D!C13)*B6", "eCIb": "=D!B25-B30", "eCIa": "=B30-D!B24*B6", "eCIr": "=(D!B24-(D!B7*D!B13+D!C7*D!C13))*B6", "eStr": "=D!B26-D!B18"},XROW={"an": 5, "uo": 6, "cs.Z1": 7, "cs.Z2": 8, "ms.Z1": 9, "ms.Z2": 10, "resB": 12, "resR": 13, "eRes": 14, "eCA": 15, "eM": 17, "ePrix": 18, "eVol": 19, "eComp": 20, "eFib": 22, "eFibQ": 23, "eFibP": 24, "eKit": 25, "eMod": 26, "eModT": 27, "eModX": 28, "bf": 30, "eCI": 31, "eCIb": 32, "eCIa": 33, "eCIr": 34, "eStr": 36};
const xl=k=>XLF[k].replace(/D!/g,"'DSCG Données'!");
/* Valeur attendue en reprenant les propres réponses de l'étudiant pour les valeurs amont : une erreur reportée n'est comptée qu'une fois. */
function attendu(k,u){const b=DS.bud,r=DS.reel,s=DS.std,M=["Z1","Z2"],qB=b.Z1.q+b.Z2.q,qR=r.Z1.q+r.Z2.q,hS=O.hS,mB=()=>b.Z1.q*u("ms.Z1")+b.Z2.q*u("ms.Z2");
  switch(k){case "uo":return (DS.fixAt+DS.varAt*u("an"))/u("an");
   case "cs.Z1":case "cs.Z2":{const m=k.slice(3);return s[m].kg*DS.pkg+s[m].kit+s[m].h*DS.taux+s[m].h*u("uo");}
   case "ms.Z1":case "ms.Z2":{const m=k.slice(3);return b[m].p-u("cs."+m);}
   case "resB":return O.caB-b.Z1.q*u("cs.Z1")-b.Z2.q*u("cs.Z2")-DS.strB;
   case "eRes":return u("resR")-u("resB");
   case "eM":return M.reduce((a,m)=>a+r[m].q*(r[m].p-u("cs."+m)),0)-mB();
   case "eVol":return (qR-qB)*mB()/qB;
   case "eComp":return r.Z1.q*u("ms.Z1")+r.Z2.q*u("ms.Z2")-qR*mB()/qB;
   case "eCI":return DS.r.ci-hS*u("uo");
   case "eCIb":return DS.r.ci-u("bf");
   case "eCIa":return u("bf")-DS.r.h*u("uo");
   case "eCIr":return (DS.r.h-hS)*u("uo");
   default:return val(k);}}
const ATT_OUV=[
 "<b>Trois ensembles de causes, par montant.</b><ul><li>Retard du Z2 : quantité −202 000 €, prix +45 000 €, soit −157 000 €. À interroger : conception et direction.</li><li>Charges de structure : dépassement de 60 000 €. À interroger : direction ; le cas n'en donne pas le détail.</li><li>Perte de savoir-faire à l'atelier : fibre −12 000 €, temps −8 750 €, rendement −12 500 €, soit −33 250 €. À interroger : production et ressources humaines.</li></ul><b>Écarts qui se répondent.</b><ul><li>Sur le Z1, les remises (−135 000 €) et le gain de volume (+145 500 €) se compensent : la politique commerciale a défendu la position sans détruire de marge.</li><li>Le retard du Z2 a deux effets contraires : moins de ventes, mais un prix plus élevé. Le prix budgété était peut-être trop bas.</li><li>Les hausses de prix d'achat (fibre +13 500 €, kit Z1 +36 000 €) sont en partie subies.</li><li>Le taux horaire monte alors que des débutants remplacent des expérimentés : les données ne l'expliquent pas. La bonne réponse est de poser la question, pas d'inventer la cause.</li></ul>",
 "<b>Actions recevables, par exemple.</b><ul><li>Un jalon de conception avec date d'alerte pour le Z2.</li><li>Un plan de formation et de fidélisation des assembleurs.</li><li>Une révision annuelle des standards.</li><li>Une double source pour le kit Z1.</li><li>Une grille de remises plafonnée.</li></ul><b>Indicateurs mensuels attendus.</b><ul><li>Part du Z2 dans les ventes, remise moyenne.</li><li>Heures par drone, kilos de fibre par drone.</li><li>Prix d'achat moyens, avancement des projets de conception.</li></ul>",
 "<b>Idées attendues.</b><ul><li>Des standards assis sur deux exercices sont fragiles : une part des écarts mesure l'erreur de prévision, non la performance.</li><li>L'analyse est annuelle et tardive : elle constate, elle n'alerte pas.</li><li>Les charges de structure (1,81 million d'euros) échappent à toute décomposition ; la conception y est noyée.</li><li>L'unité d'œuvre unique, l'heure de main-d'œuvre, est discutable pour un atelier dont les coûts dépendent aussi des essais et des modèles.</li><li>Compléments possibles : prévisions glissantes, suivi de trésorerie, indicateurs non financiers, coût cible pour les nouveaux modèles, comptabilité par activités.</li></ul>"];
const rev=k=>!!(S.ds.rev||{})[k],revTout=()=>QDSCG.every(q=>rev(q[0]));
const montre=k=>rev(k)||(!S.note&&S.ds.ok[k]===false);
const fmtV=k=>num(Math.round(val(k)*100)/100).replace("-","−");
let vuOuv={};
function progDs(){let ok=0,pts=0;const g={};QDSCG.forEach(q=>{g[q[2]]=g[q[2]]||[0,0];g[q[2]][1]++;if(S.ds.ok[q[0]]===true)ok++;if(S.ds.ok[q[0]]===true||(S.ds.co||{})[q[0]]){g[q[2]][0]++;}});Object.keys(g).forEach(k=>pts+=PTS[k]*g[k][0]/g[k][1]);return {ok,g,pts:Math.round(pts*10)/10};}
const pas=(prec,suiv)=>`<div class="row pas">${prec?`<a class="btn" href="#${prec[0]}">← ${prec[1]}</a>`:""}${suiv?`<a class="btn pri" href="#${suiv[0]}">${suiv[1]} →</a>`:""}</div>`;
function vBilan(){const P=progDs(),lu=[5,6,7].filter(i=>{const st=S.lec[i];return st&&LECONS[i].qs.every((q,k)=>st.ok[k]===true);}).length,red=S.ds.ouv.filter(x=>x&&x.trim().length>40).length,tout=P.ok===QDSCG.length;
  const et=[["Leçons 6 à 8 réussies",lu+" / 3",lu===3,"lecons"],["Valeurs justes",P.ok+" / "+QDSCG.length,tout,"ecarts"],["Tableau de passage ouvert",tout||revTout()?"oui":"non",tout||revTout(),"passage"],["Réponses rédigées du diagnostic",red+" / 3",red===3,"diagnostic"]];
  return `<div class="panel"><h2>Bilan du projet</h2><div class="grid"><div class="fact"><b>${String(P.pts).replace(".",",")} / 10</b><span>points de calcul, comptés par la page</span></div><div class="fact"><b>${S.ds.tries||0}</b><span>vérifications lancées</span></div><div class="fact"><b>10 points</b><span>restent à l'appréciation de l'enseignant</span></div></div>
  <div class="scroll"><table class="txt"><thead><tr><th>Étape</th><th>Avancement</th><th>État</th></tr></thead><tbody>${et.map(e=>`<tr><td><a href="#${e[3]}">${e[0]}</a></td><td>${e[1]}</td><td><span class="chip ${e[2]?"ok":"wait"}">${e[2]?"fait":"à terminer"}</span></td></tr>`).join("")}</tbody></table></div></div>
  <div class="panel"><h3>Points de calcul par partie</h3><div class="scroll"><table><thead><tr><th>Partie</th><th>Valeurs justes ou cohérentes</th><th>Points</th></tr></thead><tbody>${Object.keys(P.g).map(k=>`<tr><td>${k}</td><td>${P.g[k][0]} / ${P.g[k][1]}</td><td>${String(Math.round(PTS[k]*P.g[k][0]/P.g[k][1]*10)/10).replace(".",",")} / ${String(PTS[k]).replace(".",",")}</td></tr>`).join("")}</tbody></table></div><p class="note">Les points d'une partie sont proportionnels au nombre de valeurs justes ou cohérentes. Une erreur reportée n'est pénalisée qu'une fois : une valeur calculée correctement à partir d'une de vos valeurs fausses garde ses points.</p></div>
  <div class="panel"><h3>Ce qui reste à l'appréciation de l'enseignant</h3><ul><li><b>Choix et justification, 6 points :</b> hiérarchie des causes, liens entre écarts, actions et indicateurs.</li><li><b>Lecture critique, 4 points :</b> limites des standards, outils mieux adaptés à une start-up.</li></ul><p class="note">Pour la soutenance : présentez le tableau de passage, vos trois causes principales et vos trois actions, en quinze minutes.</p></div>${pas(["diagnostic","Diagnostic"],null)}`;}

function vSujet(){const M=["Z1","Z2"];return `<div class="panel"><h2>Le troisième exercice d'Atelier Zéphyr</h2><p class="lead">La société vend désormais deux modèles : le Z1, drone d'inspection courante, et le Z2, modèle haut de gamme à capteur thermique. Le budget annonçait un premier bénéfice. L'exercice se clôt en perte, alors que le nombre total de drones vendus est exactement celui prévu.</p><p>En qualité de contrôleurs de gestion, vous devez expliquer cet écart avant le comité des investisseurs.</p><p class="note">Ce module utilise des données plus détaillées que la simulation en trois années ; les deux jeux de chiffres sont indépendants.</p></div>
  <div class="panel"><h2>Annexe 1 : budget</h2><div class="grid2"><div class="scroll"><table><thead><tr><th>Ventes budgétées</th><th>Quantité</th><th>Prix unitaire</th></tr></thead><tbody>${M.map(m=>`<tr><td>${m}</td><td>${DS.bud[m].q}</td><td>${eur(DS.bud[m].p)}</td></tr>`).join("")}</tbody></table></div>
  <div class="scroll"><table><thead><tr><th>Atelier d'assemblage</th><th></th></tr></thead><tbody><tr><td>Unité d'œuvre</td><td>heure de MOD</td></tr><tr><td>Activité normale</td><td>celle du programme budgété</td></tr><tr><td>Charges fixes</td><td>${eur(DS.fixAt)}</td></tr><tr><td>Charges variables</td><td>${DS.varAt} € par heure</td></tr></tbody></table></div></div>
  <div class="scroll"><table><thead><tr><th>Standards unitaires</th><th>Z1</th><th>Z2</th><th>Coût unitaire standard</th></tr></thead><tbody><tr><td>Fibre de carbone</td><td>${DS.std.Z1.kg} kg</td><td>${DS.std.Z2.kg} kg</td><td>${DS.pkg} € le kg</td></tr><tr><td>Kit électronique et motorisation</td><td>1 kit</td><td>1 kit</td><td>${eur(DS.std.Z1.kit)} (Z1), ${eur(DS.std.Z2.kit)} (Z2)</td></tr><tr><td>Main-d'œuvre directe</td><td>${DS.std.Z1.h} h</td><td>${DS.std.Z2.h} h</td><td>${DS.taux} € l'heure</td></tr><tr><td>Charges indirectes de l'atelier</td><td>${DS.std.Z1.h} UO</td><td>${DS.std.Z2.h} UO</td><td>à calculer</td></tr></tbody></table></div><p>Charges de structure budgétées : <b>${eur(DS.strB)}</b>, fixes sur l'exercice.</p></div>
  <div class="panel"><h2>Annexe 2 : réalisations</h2><div class="grid2"><div class="scroll"><table><thead><tr><th>Ventes réelles</th><th>Quantité</th><th>Prix moyen</th></tr></thead><tbody>${M.map(m=>`<tr><td>${m}</td><td>${DS.reel[m].q}</td><td>${eur(DS.reel[m].p)}</td></tr>`).join("")}</tbody></table></div>
  <div class="scroll"><table><thead><tr><th>Coûts réels</th><th>Consommation</th><th>Coût</th></tr></thead><tbody><tr><td>Fibre de carbone</td><td>${num(DS.r.kg)} kg</td><td>${DS.r.pkg} € le kg</td></tr><tr><td>Kits Z1</td><td>${DS.reel.Z1.q}</td><td>${eur(DS.r.kit.Z1)}</td></tr><tr><td>Kits Z2</td><td>${DS.reel.Z2.q}</td><td>${eur(DS.r.kit.Z2)}</td></tr><tr><td>Main-d'œuvre directe</td><td>${num(DS.r.h)} h</td><td>${DS.r.taux} € l'heure</td></tr><tr><td>Charges indirectes</td><td>${num(DS.r.h)} UO</td><td>${eur(DS.r.ci)}</td></tr></tbody></table></div></div><p>Charges de structure réelles : <b>${eur(DS.strR)}</b>.</p><ul>${INFOS.map(x=>`<li>${x}</li>`).join("")}</ul></div>
  <div class="panel"><h2>Conventions</h2><ul><li>La production de l'exercice est égale aux ventes : ni stock, ni en-cours.</li><li>Les coûts sont suivis en coûts standards complets de production ; les charges de structure ne sont pas incorporées.</li><li>Tout écart est calculé réel moins prévu. Un écart positif sur un coût est défavorable ; un écart positif sur une marge ou un résultat est favorable.</li><li>Les écarts sur coûts se calculent par rapport à la production réelle.</li></ul></div>${pas(null,["ecarts","Calcul des écarts"])}`;}
function vEcarts(){const P=progDs(),ok=P.ok,gr=[...new Set(QDSCG.map(q=>q[2]))];
  return `<div class="panel"><div class="row" style="justify-content:space-between"><h2>Calcul des écarts</h2><span class="chip ${ok===QDSCG.length?"ok":"wait"}">${ok} valeurs justes sur ${QDSCG.length}</span></div><p class="note">Saisissez vos résultats en euros, avec leur signe (réel moins prévu). La page dit seulement si la valeur est juste. ${S.note?"Parcours noté : les réponses ne s'affichent pas.":"Après chaque vérification, toute valeur à revoir affiche la réponse attendue, la formule de calcul à la main et la formule à saisir dans Excel ou Google Sheets : corrigez-la avant de continuer."} Une valeur fausse seulement parce qu'elle reprend une de vos valeurs précédentes est signalée « cohérente », à l'arrondi près, et garde ses points. Les données sont dans « Sujet et annexes ».</p><div class="row"><button class="pri" id="ds-verif">Vérifier mes réponses</button><span class="note">${S.ds.tries?S.ds.tries+" vérification"+(S.ds.tries>1?"s":""):""}</span></div></div>
  ${gr.map(g=>`<div class="panel"><div class="row" style="justify-content:space-between"><h3>${g}</h3><span class="chip ${P.g[g][0]===P.g[g][1]?"ok":""}">${P.g[g][0]} / ${P.g[g][1]} · ${String(PTS[g]).replace(".",",")} pt${PTS[g]>1?"s":""}</span></div><div class="grid">${QDSCG.filter(q=>q[2]===g).map(q=>{const k=q[0],o=S.ds.ok[k],co=(S.ds.co||{})[k];return `<label>${q[1]}<input id="ds-${k.replace(".","-")}" data-ds="${k}" inputmode="numeric" value="${esc(S.ds.ans[k]||"")}"><span class="check ${o===true?"ok":co?"co":o===false?"ko":""}">${o===true?"Juste":co?"Cohérent avec vos valeurs précédentes : l'erreur n'est comptée qu'une fois":o===false?"À revoir":"&nbsp;"}</span>${montre(k)?`<span class="rep">Réponse attendue : <b>${fmtV(k)}</b></span>`:""}${montre(k)||(o===false&&!co&&S.ds.tries>=2)?`<span class="aide"><b>Calcul à la main :</b> ${AIDE[k]}.<br><b>Excel ou Google Sheets</b> (cellule B${XROW[k]} de la feuille « DSCG Mes écarts ») : <code>${esc(xl(k))}</code></span>`:""}</label>`;}).join("")}</div></div>`).join("")}${pas(["sujet","Sujet et annexes"],["passage","Tableau de passage"])}`;}
function vPassage(){const ok=QDSCG.filter(q=>S.ds.ok[q[0]]===true).length,open=revTout()||ok===QDSCG.length;
  if(!open)return `<div class="panel"><h2>Tableau de passage</h2><p>Le graphique de passage du résultat budgété au résultat réel s'affiche quand les ${QDSCG.length} valeurs de la page « Calcul des écarts » sont justes, ou quand l'enseignant ouvre le corrigé.</p><div class="jauge big"><i style="width:${Math.round(ok*100/QDSCG.length)}%"></i></div><p class="note">${ok} valeurs justes sur ${QDSCG.length}.</p></div>${pas(["ecarts","Calcul des écarts"],["diagnostic","Diagnostic"])}`;
  const rows=[["Résultat budgété",O.resB],["Écart sur prix de vente",O.ePrix],["Écart de volume global",O.eVol],["Écart de composition des ventes",O.eComp],["Écart sur fibre de carbone",-O.eFib],["Écart sur kits",-O.eKit],["Écart sur main-d'œuvre directe",-O.eMod],["Écart sur charges indirectes",-O.eCI],["Écart sur charges de structure",-O.eStr],["Résultat réel",O.resR]];
  return `<div class="panel"><h2>Du résultat budgété au résultat réel</h2>${cascade(O)}</div><div class="panel"><h3>Tableau de passage</h3><div class="scroll"><table><thead><tr><th>Élément</th><th>Effet sur le résultat</th></tr></thead><tbody>${rows.map((r,i)=>`<tr${i===0||i===9?' class="tot"':""}><td>${r[0]}</td><td${neg(r[1])}>${i===0||i===9?eur(r[1]):sig(r[1])+" €"}</td></tr>`).join("")}</tbody></table></div><p class="note">Contrôle : ${sig(O.eM)} (marge) ${sig(-O.eCout)} (coûts de production) ${sig(-O.eStr)} (structure) = ${sig(O.eRes)} €, égal à l'écart de résultat.</p></div>
  <div class="panel"><h3>Lecture par modèle</h3><div class="scroll"><table><thead><tr><th>Écart sur marge</th><th>Z1</th><th>Z2</th><th>Total</th></tr></thead><tbody>${[["Écart sur prix",m=>(DS.reel[m].p-DS.bud[m].p)*DS.reel[m].q],["Écart sur quantité",m=>(DS.reel[m].q-DS.bud[m].q)*O.ms[m]],["Écart sur marge",m=>DS.reel[m].q*(DS.reel[m].p-O.cs[m])-DS.bud[m].q*O.ms[m]]].map((r,i)=>{const a=r[1]("Z1"),b=r[1]("Z2");return `<tr${i===2?' class="tot"':""}><td>${r[0]}</td><td${neg(a)}>${sig(a)} €</td><td${neg(b)}>${sig(b)} €</td><td${neg(a+b)}>${sig(a+b)} €</td></tr>`;}).join("")}</tbody></table></div><p class="note">L'écart sur quantité par modèle regroupe le volume global et la composition. À interpréter dans le diagnostic : quel modèle explique l'essentiel de l'écart ?</p></div>${pas(["ecarts","Calcul des écarts"],["diagnostic","Diagnostic"])}`;}
function vDiag(){return `<div class="panel"><h2>Diagnostic et lecture critique</h2><p class="note">Ces trois réponses sont rédigées. La page les garde ; elle ne les corrige pas. ${S.note?"Parcours noté : les éléments attendus sont affichés par l'enseignant.":"Rédigez d'abord votre réponse (quelques lignes), puis comparez-la aux éléments attendus."}</p>${QOUV.map((q,i)=>{const ecrit=(S.ds.ouv[i]||"").trim().length>=40,vis=S.ds.revOuv[i]||(!S.note&&vuOuv[i]);return `<div class="quest"><label>${i+9}. ${q}<textarea id="ouv-${i}" data-ouv="${i}" class="haut">${esc(S.ds.ouv[i]||"")}</textarea></label>${S.note?"":`<div class="row"><button data-vu="${i}">${vuOuv[i]?"Cacher":"Afficher"} les éléments attendus</button></div>`}${vis?`<div class="expl">${ATT_OUV[i]}</div>`:""}</div>`;}).join("")}</div>
  <div class="panel"><h3>Ce qui est évalué</h3><div class="scroll"><table class="txt"><thead><tr><th>Compétence</th><th>Points</th><th>Ce qui compte</th></tr></thead><tbody><tr><td><b>Justesse des calculs</b></td><td>10</td><td>Les ${QDSCG.length} valeurs. Une erreur reportée n'est pénalisée qu'une fois.</td></tr><tr><td><b>Choix et justification</b></td><td>6</td><td>Hiérarchie des causes, liens entre écarts, actions et indicateurs.</td></tr><tr><td><b>Lecture critique</b></td><td>4</td><td>Limites des standards, outils mieux adaptés à une start-up.</td></tr></tbody></table></div></div>${pas(["passage","Tableau de passage"],["bilan","Bilan du projet"])}`;}

/* ---------- mode Enseignant ---------- */
let confirmReset=false,msg="";
function vConduite(){const y=annee(),dc=dClos(),manq=y<3?S.teams.filter(t=>!t.d[y]).map(t=>t.n):[];
  return `<div class="panel"><h2>Conduite de la simulation</h2><div class="row"><span class="chip">${y<3?"Année en cours : "+(y+1):"Simulation terminée"}</span>${y<3?`<button class="pri" id="clore" ${manq.length||!S.teams.length?"disabled":""}>Clôturer l'année ${y+1} et afficher les résultats</button>`:""}${dc>=0?`<button id="rouvrir">Rouvrir l'année ${dc+1}</button>`:""}</div>${manq.length?`<p class="note">En attente de décision : ${manq.map(esc).join(", ")}.</p>`:""}${y===1?`<p class="note">Année 2 : faites passer les pitchs avant la décision. Toutes les équipes reçoivent 400 000 € ; le pitch est noté, il ne change pas les chiffres.</p>`:""}</div>
  <div class="panel"><h2>Événements annuels</h2><div class="row"><button id="ev" ${dc>=0?"disabled":""}>${S.ev?"Désactiver":"Activer"} les événements</button><span class="chip ${S.ev?"ok":""}">${S.ev?"Activés":"Désactivés"}</span></div><p class="note">Un événement par année modifie une donnée du jeu. Le choix se fait avant la clôture de l'année 1. Sans événement, les résultats sont ceux du dossier enseignant.</p><div class="scroll"><table class="txt"><thead><tr><th>Année</th><th>Événement</th><th>Effet</th></tr></thead><tbody>${EVTS.map((e,i)=>`<tr><td>${i+1}</td><td><b>${e.t}</b></td><td>${e.d}</td></tr>`).join("")}</tbody></table></div></div>
  <div class="panel"><h2>Équipes</h2><p class="note">Donnez des noms d'équipe, pas des noms d'étudiants.</p>${S.teams.map((t,i)=>`<div class="row"><span class="dot" style="background:${col(i)}"></span><input id="nom-${i}" data-nom="${i}" value="${esc(t.n)}" aria-label="Nom de l'équipe ${i+1}"><button data-del="${i}" ${dc>=0?"disabled":""}>Retirer</button></div>`).join("")}<div class="row"><button id="add" ${S.teams.length>=8||dc>=0?"disabled":""}>Ajouter une équipe</button><span class="note">${dc>=0?"La liste est figée dès qu'une année est clôturée.":"Huit équipes au plus."}</span></div></div>
  <div class="panel"><h2>Réponses : afficher ou cacher</h2><div class="row"><button id="note">${S.note?"Repasser en apprentissage":"Passer en parcours noté"}</button><span class="chip ${S.note?"ko":"ok"}">${S.note?"Parcours noté : aucune réponse automatique":"Apprentissage : la bonne réponse s'affiche après chaque vérification"}</span></div>
  <p class="note">En apprentissage, l'étudiant voit la réponse attendue dès qu'une valeur est fausse, dans les leçons et dans le calcul des écarts, pour ne pas continuer avec de mauvais chiffres. La simulation en trois années ne donne jamais les réponses. Les boutons ci-dessous affichent une réponse même sans saisie, sur cet appareil.</p>
  <div class="row"><b>Calcul des écarts :</b><button data-rev="all">Tout afficher</button><button data-rev="none">Tout cacher</button><button id="ds-raz">Effacer les réponses saisies</button></div>
  ${[...new Set(QDSCG.map(q=>q[2]))].map(g=>{const ks=QDSCG.filter(q=>q[2]===g),n=ks.filter(q=>rev(q[0])).length;return `<div class="revbloc"><div class="row"><b>${g}</b><button data-rev="g:${g}">${n===ks.length?"Cacher le bloc":"Afficher le bloc"}</button><span class="note">${n} / ${ks.length} affichées</span></div><div class="seg">${ks.map(q=>`<button data-rev="k:${q[0]}" aria-pressed="${rev(q[0])}">${q[1].replace(" (€)","")}</button>`).join("")}</div></div>`;}).join("")}
  <div class="revbloc"><div class="row"><b>Questions rédigées :</b></div><div class="seg">${QOUV.map((q,i)=>`<button data-rev="o:${i}" aria-pressed="${!!S.ds.revOuv[i]}">Question ${i+9} : éléments attendus</button>`).join("")}</div></div></div>`;}
function note(t){const r=calc(t),n=dClos()+1;let c=0;for(let y=0;y<n;y++){const s=t.s[y]||{};if(["v","ca","res","fin"].every(k=>s["ok"+k]===true))c+=2;}
  const surv=n>0&&!r.slice(0,n).some(a=>a.fin<0)?2:0,man=BAREME.reduce((s,b)=>s+Math.min(b[2],Math.max(0,Number(t.g[b[0]])||0)),0);return {c,surv,man,tot:c+surv+man};}
function vNotation(){if(!S.teams.length)return vide();return `<div class="panel"><h2>Notation des équipes</h2><p class="note">Les points de calcul (2 par année dont les quatre valeurs sont justes) et de survie (trésorerie jamais négative) sont comptés par la page sur les années clôturées. Vous saisissez les autres. Le rang de l'équipe ne donne aucun point.</p>
  <div class="scroll"><table><thead><tr><th>Équipe</th><th>Calculs /6</th><th>Survie /2</th>${BAREME.map(b=>`<th title="${b[1]}">${b[1].split(" ")[0]} /${b[2]}</th>`).join("")}<th>Total /20</th></tr></thead><tbody>${S.teams.map((t,i)=>{const n=note(t);return `<tr><td>${esc(t.n)}</td><td>${n.c}</td><td>${n.surv}</td>${BAREME.map(b=>`<td><input class="pt" id="g-${i}-${b[0]}" data-g="${i}-${b[0]}" type="number" min="0" max="${b[2]}" step="0.5" value="${esc(t.g[b[0]]==null?"":t.g[b[0]])}" aria-label="${b[1]}, ${esc(t.n)}"></td>`).join("")}<td><b>${String(n.tot).replace(".",",")}</b></td></tr>`;}).join("")}</tbody></table></div>
  <ul class="note">${BAREME.map(b=>`<li>${b[1]} : ${b[2]} points</li>`).join("")}</ul></div>
  <div class="panel"><h2>Suivi des calculs à la main</h2><div class="row"><button id="corr">${S.corr?"Masquer":"Afficher"} les valeurs exactes</button></div><div class="scroll"><table><thead><tr><th>Équipe</th><th>Année</th><th>Vérifications</th><th>Ventes</th><th>Chiffre d'affaires</th><th>Résultat</th><th>Trésorerie</th></tr></thead><tbody>${S.teams.map(t=>calc(t).map((a,i)=>{const s=t.s[i]||{},c=k=>s["ok"+k]===true?'<span class="check ok">juste</span>':s["ok"+k]===false?'<span class="check ko">à revoir</span>':"non saisi";return `<tr><td>${esc(t.n)}</td><td>${i+1}</td><td>${s.essais||0}</td>${["v","ca","res","fin"].map(k=>`<td>${c(k)}${S.corr?" · "+num(a[k]):""}</td>`).join("")}</tr>`;}).join("")).join("")||'<tr><td colspan="7">Aucune décision enregistrée.</td></tr>'}</tbody></table></div></div>
  <div class="panel"><h2>Justifications des équipes</h2>${S.teams.map(t=>`<h3>${esc(t.n)}</h3>${[0,1,2].map(y=>(t.j[y]||[]).some(x=>x)?`<p class="note"><b>Année ${y+1}.</b> ${(t.j[y]||[]).map((x,i)=>x?`${QJUST[i]} <i>${esc(x)}</i>`:"").filter(Boolean).join(" · ")}</p>`:"").join("")||'<p class="note">Rien de saisi.</p>'}`).join("")}</div>`;}
function vReperes(){const p=PR();return `<div class="panel"><h2>Six stratégies types</h2><p class="note">À ne pas projeter avant le bilan final. ${S.ev?"Calculées avec les événements activés.":"Les trois stratégies les plus rentables passent toutes sous zéro de trésorerie en fin d'année 1."}</p><div class="scroll"><table><thead><tr><th>Stratégie</th><th>Ventes an 1 / 2 / 3</th><th>Trésorerie fin an 1</th><th>Résultat cumulé</th><th>Trésorerie finale</th></tr></thead><tbody>${TYPES.map(([n,d])=>{const r=simul(d,p),cum=r.reduce((s,o)=>s+o.res,0);return `<tr><td>${n}</td><td>${r.map(o=>o.v).join(" / ")}</td><td${neg(r[0].fin)}>${eur(r[0].fin)}</td><td${neg(cum)}>${eur(cum)}</td><td${neg(r[2].fin)}>${eur(r[2].fin)}</td></tr>`;}).join("")}</tbody></table></div></div>
  <div class="panel"><h2>Quatre idées pour le bilan</h2><ol><li>Un business model est un ensemble : changer le prix change aussi le segment de clients et les canaux.</li><li>Une perte de démarrage est normale quand les charges fixes arrivent avant les ventes.</li><li>Résultat et trésorerie ne racontent pas la même histoire dans une vraie entreprise ; ici ils sont confondus par simplification.</li><li>Un investissement coûte tout de suite et rapporte plus tard : il faut pouvoir attendre.</li></ol><p class="note">Limite connue : la stratégie « R&amp;D tôt, puis récolte » gagne nettement, et arrêter la R&amp;D en année 3 est payant parce que le jeu s'arrête. À faire dire aux étudiants : que se passerait-il en année 4 ?</p></div>
  <div class="panel"><h2>Fichiers de l'enseignant</h2><div class="row"><button class="pri" data-dl="complet">Télécharger le classeur complet (Excel)</button><span class="note">${esc(dlMsg)}</span></div><p class="note">Le classeur complet contient le calcul pas à pas, la simulation à formules, les six stratégies et tous les écarts du projet DSCG avec leur formule en clair et deux contrôles à zéro.</p></div>
  <div class="panel"><h2>Corrigé du contrôle de gestion</h2><div class="scroll"><table><thead><tr><th>Valeur attendue</th><th>Montant</th><th>Calcul à la main</th><th>Excel ou Google Sheets, feuille « DSCG Mes écarts »</th></tr></thead><tbody>${QDSCG.map(q=>`<tr><td>${q[1]}</td><td${neg(val(q[0]))}>${num(val(q[0])).replace("-","−")}</td><td class="g">${AIDE[q[0]]}</td><td class="g">B${XROW[q[0]]} : <code>${esc(xl(q[0]))}</code></td></tr>`).join("")}</tbody></table></div><p class="note">Lecture : le Z1 est presque à l'équilibre (remises −135 000 €, volume +145 500 €). L'essentiel de l'écart commercial vient du retard du Z2. Le départ des assembleurs explique à la fois le temps, le rendement et le gâchis de fibre.</p></div>`;}
function vSauv(){return `<div class="panel"><h2>Sauvegarde entre deux séances</h2><p class="note">Tout est gardé dans ce navigateur seulement : équipes, décisions, textes, notes. Pour reprendre sur un autre poste ou par sécurité, copiez le code ci-dessous et gardez-le ; collez-le ici et chargez-le à la séance suivante.</p><textarea id="code" class="code" aria-label="Code de sauvegarde">${esc(JSON.stringify(S))}</textarea>
  <div class="row"><button id="copier">Copier le code</button><button id="charger">Charger le code collé</button>${confirmReset?`<button class="danger" id="reset2">Confirmer : tout effacer</button><button id="reset0">Annuler</button>`:`<button class="danger" id="reset">Nouvelle partie</button>`}<span class="note">${esc(msg)}</span></div></div>`;}

/* ---------- navigation et actions ---------- */
const VUES={bilan:vBilan,accueil:vAccueil,manuel:vManuel,texte:vTexte,excel:vExcel,lecons:vLecons,fichiers:vFichiers,cas:vCas,canevas:vCanevas,environnement:vEnv,ressources:vRess,marche:vMarche,notions:vNotions,classe:vClasse,decisions:vDecisions,bord:vBord,detail:vDetail,regles:vRegles,sujet:vSujet,ecarts:vEcarts,passage:vPassage,diagnostic:vDiag,conduite:vConduite,notation:vNotation,reperes:vReperes,sauvegarde:vSauv};
const vue=()=>{const h=location.hash.slice(1);return VUES[h]?h:"accueil";};
function render(){let v=vue(),m=MODES.find(M=>M[2].some(p=>p[0]===v));
  if(PARC==="du"&&m[0]==="controle"){v="accueil";m=MODES[0];}
  document.getElementById("parc").innerHTML=barreParc();
  document.getElementById("modes").innerHTML=MODES.filter(M=>(M[0]!=="enseignant"||M===m)&&(M[0]!=="controle"||PARC!=="du")).map(M=>`<a href="#${M[2][0][0]}" ${M===m?'aria-current="true"':""}>${M[1]}</a>`).join("");
  document.getElementById("nav").innerHTML=m[2].map(p=>`<a href="#${p[0]}" ${p[0]===v?'aria-current="page"':""}>${p[1]}</a>`).join("");
  document.getElementById("app").innerHTML=`<section class="view">${(!PARC&&!TEACH.includes(v))?choixParcours():((TEACH.includes(v)?"":changeBar())+VUES[v]())}</section>`;}
const upd=()=>{save();render();};
const app=document.getElementById("app");
app.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;const y=annee(),id=b.id,ds=b.dataset;
  if(id==="t-go"){timer.run=!timer.run;clearInterval(timer.id);if(timer.run)timer.id=setInterval(tick,1000);render();}
  else if(id==="t-20"||id==="t-10"){timer.left=(id==="t-20"?20:10)*60;timer.run=false;clearInterval(timer.id);render();}
  else if(ds.parc){setParc(ds.parc==="reset"?"":ds.parc);render();window.scrollTo(0,0);}
  else if(ds.sel){S.sel=+ds.sel;upd();}
  else if(ds.theme){theme=ds.theme;render();}
  else if(ds.filtre){filtre=ds.filtre;render();}
  else if(ds.dec&&y<3){const t=team();if(!t._p||t._p.y!==y)t._p=Object.assign({y},t.d[y]||{});t._p[ds.dec]=+ds.i;
    if(["p","c","r"].every(x=>t._p[x]!==undefined)){t.d[y]={p:t._p.p,c:t._p.c,r:t._p.r};const s=t.s[y]=t.s[y]||{};["v","ca","res","fin"].forEach(k=>delete s["ok"+k]);}upd();}
  else if(id==="verif"){const t=team(),a=calc(t)[y],s=t.s[y]=t.s[y]||{};["v","ca","res","fin"].forEach(k=>{s[k]=document.getElementById("in-"+k).value;const n=parse(s[k]);if(n===null)delete s["ok"+k];else s["ok"+k]=n===a[k];});s.essais=(s.essais||0)+1;upd();}
  else if(id==="clore"){S.clos[y]=true;S.sel=y;timer.left=1200;timer.run=false;clearInterval(timer.id);save();if(vue()!=="classe")location.hash="#classe";else render();}
  else if(ds.lec!==undefined){lec=+ds.lec;dlMsg="";render();window.scrollTo(0,0);}
  else if(id==="lec-verif"){const L=LECONS[lec],st=S.lec[lec]=S.lec[lec]||{ans:[],ok:[],n:0};L.qs.forEach((q,i)=>{if(q.choix){const r=document.querySelector(`input[name="lq-${lec}-${i}"]:checked`);st.ans[i]=r?r.value:"";st.ok[i]=r?+r.value===q.a:null;}else{st.ans[i]=document.getElementById(`lq-${lec}-${i}`).value;const n=parse(st.ans[i]);st.ok[i]=n===null?null:Math.abs(n-q.a)<0.5;}});st.n++;upd();}
  else if(ds.dl){telecharger(ds.dl);}
  else if(id==="t-next"){tStep=Math.min(tStep+1,TEXTE.length-1);render();}
  else if(id==="t-prev"){tStep=Math.max(tStep-1,0);render();}
  else if(id==="rouvrir"){S.clos[dClos()]=false;S.sel=Math.max(0,dClos());upd();}
  else if(id==="ev"){S.ev=!S.ev;S.teams.forEach(t=>t.s.forEach(s=>["v","ca","res","fin"].forEach(k=>delete s["ok"+k])));upd();}
  else if(id==="add"){S.teams.push(newTeam("Équipe "+(S.teams.length+1)));upd();}
  else if(ds.del){S.teams.splice(+ds.del,1);upd();}
  else if(id==="corr"){S.corr=!S.corr;upd();}
  else if(id==="ds-verif"){QDSCG.forEach(q=>{const k=q[0],el=document.getElementById("ds-"+k.replace(".","-"));if(el)S.ds.ans[k]=el.value;const n=parse(S.ds.ans[k]);if(n===null)delete S.ds.ok[k];else S.ds.ok[k]=Math.abs(n-val(k))<0.5;});S.ds.co={};const u=k=>{const n=parse(S.ds.ans[k]);return n===null?val(k):n;};QDSCG.forEach(q=>{const k=q[0],n=parse(S.ds.ans[k]);if(n!==null&&S.ds.ok[k]===false&&attendu(k,u)!==val(k)){const at=attendu(k,u),tol=Math.max(1,Math.abs(at)*0.01)+(/^(eCI|eCIa|eCIr|resB|eM|eComp|eVol)$/.test(k)?50:0);if(Math.abs(n-at)<=tol)S.ds.co[k]=true;}});S.ds.tries=(S.ds.tries||0)+1;upd();}
  else if(id==="note"){S.note=!S.note;upd();}
  else if(ds.rev){const r=ds.rev,R=S.ds.rev;if(r==="all"){QDSCG.forEach(q=>R[q[0]]=true);QOUV.forEach((q,i)=>S.ds.revOuv[i]=true);}else if(r==="none"){S.ds.rev={};S.ds.revOuv={};}
    else if(r[0]==="g"){const ks=QDSCG.filter(q=>q[2]===r.slice(2)).map(q=>q[0]),on=!ks.every(k=>R[k]);ks.forEach(k=>{if(on)R[k]=true;else delete R[k];});}
    else if(r[0]==="k"){const k=r.slice(2);if(R[k])delete R[k];else R[k]=true;}else if(r[0]==="o"){const i=+r.slice(2);S.ds.revOuv[i]=!S.ds.revOuv[i];}upd();}
  else if(ds.vu!==undefined){const i=+ds.vu,el=document.getElementById("ouv-"+i);if(el){S.ds.ouv[i]=el.value;save();}vuOuv[i]=!vuOuv[i];render();}
  else if(id==="ds-raz"){S.ds.ans={};S.ds.ok={};S.ds.co={};S.ds.tries=0;upd();}
  else if(id==="copier"){const ta=document.getElementById("code");try{navigator.clipboard.writeText(ta.value).then(()=>{msg="Code copié.";render();},()=>{ta.select();});}catch(x){ta.select();}}
  else if(id==="charger"){try{const o=JSON.parse(document.getElementById("code").value);if(!valide(o))throw 0;S=o;S.lec=S.lec||{};S.ds.rev=S.ds.rev||{};S.ds.revOuv=S.ds.revOuv||{};msg="Partie chargée.";}catch(x){msg="Code illisible : collez le code complet, sans le modifier.";}upd();}
  else if(id==="reset"){confirmReset=true;render();}
  else if(id==="reset0"){confirmReset=false;render();}
  else if(id==="reset2"){confirmReset=false;S=exemple();S.lec={};S.exemple=false;S.clos=[false,false,false];S.teams=[];msg="Nouvelle partie : ajoutez vos équipes dans la page Conduite.";upd();}
});
app.addEventListener("change",e=>{const el=e.target,ds=el.dataset;
  if(el.id==="eq"){S.eq=+el.value;upd();}
  else if(ds.nom!==undefined){S.teams[+ds.nom].n=el.value.trim()||"Équipe "+(+ds.nom+1);save();}
  else if(ds.cv!==undefined){team().cv[ds.cv]=el.value;save();}
  else if(ds.j){const [y,i]=ds.j.split("-").map(Number),t=team();t.j[y]=t.j[y]||["","",""];t.j[y][i]=el.value;save();}
  else if(ds.ouv!==undefined){S.ds.ouv[+ds.ouv]=el.value;save();}
  else if(ds.g){const k=ds.g.indexOf("-"),i=+ds.g.slice(0,k);S.teams[i].g[ds.g.slice(k+1)]=el.value;upd();}
});
document.getElementById("parc").addEventListener("click",e=>{const b=e.target.closest("button[data-parc]");if(!b)return;setParc(b.dataset.parc==="reset"?"":b.dataset.parc);if(vue()!=="accueil")location.hash="#accueil";else render();window.scrollTo(0,0);});
window.addEventListener("hashchange",render);
render();
